insert into public.dish_archetypes (id, slug, canonical_label, description) values
  ('3c7fe8f2-eb8d-4cde-a960-5c63622d20dd', 'fried-ripe-plantain', 'Fried ripe plantain', 'Ripe plantain fried until caramelised, as a side or snack, across West Africa, the Caribbean, Latin America and South India.'),
  ('176638a3-c660-493f-ae74-3963824c461f', 'legume-and-rice-staple', 'Legumes cooked with rice', 'Rice simmered with beans or peas as an everyday staple: rice and beans, rice and peas, moros, waakye.'),
  ('5391d651-d964-46a0-a5ea-3570271fd8ba', 'smoky-spiced-chicken', 'Smoky spiced chicken', 'Chicken marinated in a pungent spice paste and roasted or grilled until charred.'),
  ('07f3dc87-834f-4d07-a1e5-69aba6aa29e0', 'tomato-pepper-rice', 'Rice cooked in tomato and pepper', 'Rice steamed in a reduced tomato-pepper base: jollof and its relatives.'),
  ('d0af582e-487b-48a9-a842-27dbf1f8d9c3', 'leafy-green-stew', 'Stewed leafy greens', 'Greens cooked down with aromatics, oil and often protein: efo riro, callaloo, palak, sukuma wiki.'),
  ('7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', 'stewed-legumes', 'Spiced stewed legumes', 'Lentils, beans or chickpeas simmered with aromatics: dal, misir wot, red red, curry chana.'),
  ('bf173926-2a08-48b1-afe3-dd73b638e676', 'eggs-in-tomato-sauce', 'Eggs in a spiced tomato sauce', 'Eggs cooked in or with a peppery tomato base: shakshuka, huevos rancheros, yam and egg sauce.'),
  ('c7a8dba1-2093-4b28-a07a-8ad9f1308085', 'bean-fritters-and-cakes', 'Bean fritters and steamed bean cakes', 'Ground beans whipped and fried or steamed: akara, moi moi.'),
  ('9381f61f-9bda-4476-aef4-376d2e8528b5', 'maize-porridge-and-swallow', 'Maize porridge and swallows', 'Cornmeal cooked thick or soft: ugali, pap, cornmeal porridge, arepas.'),
  ('e09cf848-8624-4f38-a641-4fb88997ff54', 'braised-chicken-in-sauce', 'Chicken braised in a rich sauce', 'Chicken simmered in a spiced sauce: curry chicken, yassa, karahi, adobo, machboos.')
insert into public.recipes (id, slug, title, summary, cuisine_tags, meals, recipe, app_ingredients, origin_type, origin_ref, verification_status, status, plate_role, dish_archetype_id, flavor_tags, local_dish_names, prep_minutes, cook_minutes, servings) values
  ('ng_jollof', 'ng-jollof', 'Party Jollof Rice with Roast Chicken', null, array['Nigeria']::text[], array['l', 'd']::text[], '{"id":"ng_jollof","name":"Party Jollof Rice with Roast Chicken","countries":["Nigeria"],"meals":["l","d"],"activeMin":30,"totalMin":75,"spice":2,"batch":true,"ingredients":[{"key":"chicken","qty":1000},{"key":"rice","qty":500},{"key":"tomato","qty":500},{"key":"redpepper","qty":200},{"key":"scotch","qty":10},{"key":"onion","qty":300},{"key":"tomatopaste","qty":70},{"key":"oil","qty":80},{"key":"stock","qty":700},{"key":"curry","qty":5},{"key":"thyme","qty":3},{"key":"bay","qty":2}],"steps":["Season {chicken} with {curry*0.5}, {thyme*0.5} and salt. Roast at 220 °C until golden and cooked through [t35].","Blend {tomato}, {redpepper}, {scotch} and {onion*0.5} until smooth.","Slice the remaining {onion*0.5}. Heat {oil} in a heavy pot, fry the onion 3 minutes, then add {tomatopaste} and fry until it darkens to brick red [t5].","Pour in the blend with the rest of the curry and thyme and {bay}. Cook uncovered, stirring often, until reduced by half and the oil rises to the top [t20].","Rinse {rice} until the water runs clear. Stir it into the base with {stock}. Cover with foil and a lid and cook on the lowest heat [t30]. Shake the pot instead of stirring.","Done when the grains are tender but separate. Let a light crust form at the bottom for smoky party flavour, then serve with the chicken."],"source":{"type":"library"},"archetype":"tomato-pepper-rice"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '07f3dc87-834f-4d07-a1e5-69aba6aa29e0', array[]::text[], '[]'::jsonb, 30, 45, 4),
  ('ng_efo', 'ng-efo', 'Efo Riro with Boiled Yam', null, array['Nigeria']::text[], array['d']::text[], '{"id":"ng_efo","name":"Efo Riro with Boiled Yam","countries":["Nigeria"],"meals":["d"],"activeMin":30,"totalMin":50,"spice":2,"batch":true,"ingredients":[{"key":"spinach","qty":600},{"key":"beef","qty":600},{"key":"redpepper","qty":200},{"key":"scotch","qty":10},{"key":"onion","qty":200},{"key":"palmoil","qty":60},{"key":"crayfish","qty":15},{"key":"stock","qty":300},{"key":"yam","qty":1000}],"steps":["Cut {beef} into chunks, season with salt and half the onion, and simmer in {stock} until tender [t30]. Keep the broth.","Peel {yam}, cut into thick rounds and boil in salted water until a knife slides in easily [t20].","Blend {redpepper} and {scotch} coarsely. Wash and roughly chop {spinach}, then squeeze out the water.","Warm {palmoil} gently (don''t let it smoke). Fry the remaining {onion*0.5}, add the pepper blend and fry until thick [t10].","Add the beef, a splash of broth and {crayfish}. Fold in the spinach and cook just until wilted and bright green [t3]. Serve with the yam."],"source":{"type":"library"},"archetype":"leafy-green-stew"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'd0af582e-487b-48a9-a842-27dbf1f8d9c3', array[]::text[], '[]'::jsonb, 30, 20, 4),
  ('ng_moimoi', 'ng-moimoi', 'Moi Moi (Steamed Bean Pudding)', null, array['Nigeria']::text[], array['b', 'l']::text[], '{"id":"ng_moimoi","name":"Moi Moi (Steamed Bean Pudding)","countries":["Nigeria"],"meals":["b","l"],"activeMin":25,"totalMin":80,"spice":1,"batch":false,"ingredients":[{"key":"blackeyed","qty":400},{"key":"redpepper","qty":150},{"key":"onion","qty":100},{"key":"oil","qty":60},{"key":"eggs","qty":3},{"key":"crayfish","qty":10},{"key":"stock","qty":250}],"steps":["Soak {blackeyed} for 15 minutes, then rub between your palms to slip off the skins; rinse until mostly skinless [t15].","Hard-boil {eggs} [t10], cool and halve.","Blend the beans with {redpepper}, {onion} and {stock} into a smooth, thick batter.","Stir in {oil}, {crayfish} and salt. Divide into greased ramekins or foil packets and tuck half an egg into each.","Steam over simmering water, topping up as needed [t45]. Set when a knife comes out clean."],"source":{"type":"library"},"archetype":"bean-fritters-and-cakes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'c7a8dba1-2093-4b28-a07a-8ad9f1308085', array[]::text[], '[]'::jsonb, 25, 55, 4),
  ('ng_akara', 'ng-akara', 'Akara with Agege Bread', null, array['Nigeria']::text[], array['b']::text[], '{"id":"ng_akara","name":"Akara with Agege Bread","countries":["Nigeria"],"meals":["b"],"activeMin":25,"totalMin":40,"spice":1,"batch":false,"ingredients":[{"key":"blackeyed","qty":300},{"key":"onion","qty":80},{"key":"scotch","qty":5},{"key":"oil","qty":400},{"key":"bread","qty":400}],"steps":["Soak {blackeyed} 15 minutes and rub off the skins [t15].","Blend with {onion} and {scotch} using as little water as possible. Whisk the batter for 3 minutes until fluffy — this is what makes akara light.","Heat {oil} to 175 °C. Drop in spoonfuls of batter and fry, turning, until deep golden [t6].","Drain on paper and serve hot, tucked into {bread}."],"source":{"type":"library"},"archetype":"bean-fritters-and-cakes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'c7a8dba1-2093-4b28-a07a-8ad9f1308085', array[]::text[], '[]'::jsonb, 25, 15, 4),
  ('ng_yamegg', 'ng-yamegg', 'Yam & Egg Sauce', null, array['Nigeria']::text[], array['b']::text[], '{"id":"ng_yamegg","name":"Yam & Egg Sauce","countries":["Nigeria"],"meals":["b"],"activeMin":20,"totalMin":30,"spice":2,"batch":false,"ingredients":[{"key":"yam","qty":800},{"key":"eggs","qty":6},{"key":"tomato","qty":300},{"key":"onion","qty":100},{"key":"scotch","qty":5},{"key":"oil","qty":40}],"steps":["Peel and cube {yam}; boil in salted water until fork-tender [t15].","Meanwhile dice {tomato}, {onion} and {scotch}. Fry the onion in {oil} for 2 minutes, add tomato and scotch and cook down [t6].","Pour in beaten {eggs} and stir gently until fully set, with no runny parts. Serve over the yam."],"source":{"type":"library"},"archetype":"eggs-in-tomato-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'bf173926-2a08-48b1-afe3-dd73b638e676', array[]::text[], '[]'::jsonb, 20, 10, 4),
  ('ng_peppersoup', 'ng-peppersoup', 'Chicken Pepper Soup', null, array['Nigeria']::text[], array['l', 'd']::text[], '{"id":"ng_peppersoup","name":"Chicken Pepper Soup","countries":["Nigeria"],"meals":["l","d"],"activeMin":15,"totalMin":50,"spice":3,"batch":true,"ingredients":[{"key":"chicken","qty":1000},{"key":"peppersoup","qty":15},{"key":"scotch","qty":10},{"key":"onion","qty":150},{"key":"basil","qty":20},{"key":"stock","qty":1500},{"key":"potato","qty":600}],"steps":["Cut {chicken} into pieces. Put in a pot with chopped {onion}, {peppersoup}, salt and {stock}.","Bring to a boil, then simmer [t25].","Add cubed {potato} and pounded {scotch}; simmer until the potatoes are tender and the chicken is cooked through [t15].","Tear in {basil} (stands in for scent leaf) and serve steaming."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 35, 4),
  ('ng_egusi', 'ng-egusi', 'Egusi Soup with Eba', null, array['Nigeria']::text[], array['d']::text[], '{"id":"ng_egusi","name":"Egusi Soup with Eba","countries":["Nigeria"],"meals":["d"],"activeMin":35,"totalMin":60,"spice":2,"batch":true,"ingredients":[{"key":"egusi","qty":250},{"key":"spinach","qty":400},{"key":"beef","qty":600},{"key":"palmoil","qty":80},{"key":"onion","qty":150},{"key":"scotch","qty":10},{"key":"crayfish","qty":20},{"key":"stock","qty":800},{"key":"garri","qty":400}],"steps":["Simmer {beef} in {stock} with half the onion and salt until tender [t30].","Blend the remaining {onion*0.5} and mix with {egusi} and a little water into a thick paste.","Warm {palmoil}, add the egusi paste in spoonfuls and fry undisturbed for 5 minutes, then stir and fry until curdled and nutty [t10].","Add the beef and broth, {scotch} and {crayfish}. Simmer [t10]. Fold in chopped {spinach} and cook 3 minutes.","Eba: pour {garri} into about 2½ times its volume of just-boiled water, rest 2 minutes, then stir hard into a smooth, firm dough."],"source":{"type":"library"},"archetype":"leafy-green-stew"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'd0af582e-487b-48a9-a842-27dbf1f8d9c3', array[]::text[], '[]'::jsonb, 35, 25, 4),
  ('gh_redred', 'gh-redred', 'Red Red with Fried Plantain', null, array['Ghana']::text[], array['l', 'd']::text[], '{"id":"gh_redred","name":"Red Red with Fried Plantain","countries":["Ghana"],"meals":["l","d"],"activeMin":25,"totalMin":60,"spice":1,"batch":true,"ingredients":[{"key":"blackeyed","qty":500},{"key":"plantain","qty":1000},{"key":"tomato","qty":400},{"key":"onion","qty":200},{"key":"palmoil","qty":60},{"key":"ginger","qty":20},{"key":"scotch","qty":5},{"key":"oil","qty":100}],"steps":["Simmer {blackeyed} in plenty of water until soft but holding shape [t40]. Drain.","Fry chopped {onion} in {palmoil}, add grated {ginger}, chopped {tomato} and {scotch}; cook to a thick sauce [t10].","Stir in the beans and simmer 5 minutes until everything turns red red.","Slice ripe {plantain} on the diagonal and fry in {oil} until caramelised on both sides [t6]."],"source":{"type":"library"},"archetype":"stewed-legumes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', array[]::text[], '[]'::jsonb, 25, 35, 4),
  ('sn_yassa', 'sn-yassa', 'Poulet Yassa', null, array['Senegal']::text[], array['d']::text[], '{"id":"sn_yassa","name":"Poulet Yassa","countries":["Senegal"],"meals":["d"],"activeMin":25,"totalMin":90,"spice":1,"batch":true,"ingredients":[{"key":"chicken","qty":1000},{"key":"onion","qty":900},{"key":"lemon","qty":400},{"key":"mustard","qty":30},{"key":"garlic","qty":20},{"key":"oil","qty":60},{"key":"rice","qty":400},{"key":"scotch","qty":5}],"steps":["Marinate {chicken} with the juice of {lemon}, {mustard}, minced {garlic}, half the oil and sliced {onion} for at least 30 minutes [t30].","Lift out the chicken and sear in the remaining {oil*0.5} until browned. Set aside.","Cook the onions from the marinade slowly until soft and golden [t20], then return the chicken with the marinade and a whole {scotch}.","Cover and simmer until the chicken is cooked through [t25]. Meanwhile cook {rice}."],"source":{"type":"library"},"archetype":"braised-chicken-in-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'e09cf848-8624-4f38-a641-4fb88997ff54', array[]::text[], '[]'::jsonb, 25, 65, 4),
  ('cm_pouletdg', 'cm-pouletdg', 'Poulet DG', null, array['Cameroon']::text[], array['d']::text[], '{"id":"cm_pouletdg","name":"Poulet DG","countries":["Cameroon"],"meals":["d"],"activeMin":30,"totalMin":60,"spice":1,"batch":false,"ingredients":[{"key":"chicken","qty":1000},{"key":"plantain","qty":1000},{"key":"carrot","qty":200},{"key":"greenbeans","qty":200},{"key":"redpepper","qty":200},{"key":"onion","qty":200},{"key":"garlic","qty":10},{"key":"ginger","qty":15},{"key":"tomato","qty":200},{"key":"oil","qty":120}],"steps":["Season {chicken} with {garlic}, {ginger} and salt; brown in half the {oil} [t10].","Fry sliced ripe {plantain} in the rest of the oil until golden; set aside.","Add {onion}, {tomato}, sliced {carrot}, {greenbeans} and {redpepper} to the chicken with 200 ml water; simmer until the chicken is cooked through [t20].","Fold in the plantains and warm through."],"source":{"type":"library"},"archetype":"braised-chicken-in-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'e09cf848-8624-4f38-a641-4fb88997ff54', array[]::text[], '[]'::jsonb, 30, 30, 4),
  ('et_misir', 'et-misir', 'Misir Wot with Injera', null, array['Ethiopia']::text[], array['l', 'd']::text[], '{"id":"et_misir","name":"Misir Wot with Injera","countries":["Ethiopia"],"meals":["l","d"],"activeMin":20,"totalMin":50,"spice":2,"batch":true,"ingredients":[{"key":"lentils","qty":400},{"key":"onion","qty":400},{"key":"berbere","qty":25},{"key":"garlic","qty":15},{"key":"ginger","qty":15},{"key":"tomatopaste","qty":30},{"key":"oil","qty":60},{"key":"flatbread","qty":400}],"steps":["Cook finely chopped {onion} in a dry pot, stirring, until soft and jammy [t10], then add {oil}.","Add {berbere}, {garlic}, {ginger} and {tomatopaste}; cook 3 minutes.","Add {lentils} and 1 L water; simmer, stirring, until thick and soft [t25].","Serve with injera, or {flatbread} if injera isn''t available."],"source":{"type":"library"},"archetype":"stewed-legumes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', array[]::text[], '[]'::jsonb, 20, 30, 4),
  ('ke_sukuma', 'ke-sukuma', 'Sukuma Wiki & Ugali with Beef', null, array['Kenya']::text[], array['d']::text[], '{"id":"ke_sukuma","name":"Sukuma Wiki & Ugali with Beef","countries":["Kenya"],"meals":["d"],"activeMin":25,"totalMin":35,"spice":1,"batch":false,"ingredients":[{"key":"kale","qty":600},{"key":"onion","qty":150},{"key":"tomato","qty":300},{"key":"beefmince","qty":400},{"key":"cornmeal","qty":500},{"key":"oil","qty":30}],"steps":["Brown {beefmince} in {oil} until no pink remains [t6].","Add {onion} and {tomato}; cook down [t5]. Add finely sliced {kale} and cook just until tender [t5].","Ugali: bring 1.2 L water to a boil, gradually add {cornmeal} and stir hard with a wooden spoon until thick and pulling from the sides [t10]."],"source":{"type":"library"},"archetype":"leafy-green-stew"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'd0af582e-487b-48a9-a842-27dbf1f8d9c3', array[]::text[], '[]'::jsonb, 25, 10, 4),
  ('za_chakalaka', 'za-chakalaka', 'Chakalaka & Pap with Boerewors', null, array['South Africa']::text[], array['d']::text[], '{"id":"za_chakalaka","name":"Chakalaka & Pap with Boerewors","countries":["South Africa"],"meals":["d"],"activeMin":25,"totalMin":40,"spice":2,"batch":false,"ingredients":[{"key":"sausage","qty":600},{"key":"onion","qty":150},{"key":"redpepper","qty":200},{"key":"carrot","qty":300},{"key":"bakedbeans","qty":400},{"key":"curry","qty":10},{"key":"garlic","qty":10},{"key":"cornmeal","qty":400},{"key":"oil","qty":30},{"key":"scotch","qty":5}],"steps":["Grill or pan-fry {sausage} until browned and cooked through [t15].","Chakalaka: fry {onion}, {redpepper}, {garlic}, {scotch} and {curry} in {oil}; add grated {carrot} [t8], then {bakedbeans}; simmer 5 minutes.","Pap: whisk {cornmeal} into 1.2 L boiling water, cover and cook on low, stirring now and then [t20]."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 15, 4),
  ('jm_ackee', 'jm-ackee', 'Ackee & Saltfish with Fried Plantain', null, array['Jamaica']::text[], array['b', 'l']::text[], '{"id":"jm_ackee","name":"Ackee & Saltfish with Fried Plantain","countries":["Jamaica"],"meals":["b","l"],"activeMin":25,"totalMin":40,"spice":1,"batch":false,"ingredients":[{"key":"ackee","qty":540},{"key":"saltfish","qty":250},{"key":"onion","qty":150},{"key":"redpepper","qty":150},{"key":"tomato","qty":200},{"key":"scotch","qty":5},{"key":"thyme","qty":2},{"key":"oil","qty":40},{"key":"plantain","qty":500}],"steps":["Soak {saltfish} overnight, or boil it in fresh water twice for 10 minutes each to remove the salt [t20]. Flake, discarding bones.","Fry sliced {onion}, {redpepper} and {scotch} in half the {oil} with {thyme} until soft [t5].","Add the saltfish and chopped {tomato}; cook 3 minutes.","Drain {ackee} and fold in very gently so it stays in pieces. Heat through [t3].","Fry sliced {plantain} in the remaining oil until golden."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 15, 4),
  ('jm_curry', 'jm-curry', 'Curry Chicken with Rice', null, array['Jamaica']::text[], array['d']::text[], '{"id":"jm_curry","name":"Curry Chicken with Rice","countries":["Jamaica"],"meals":["d"],"activeMin":25,"totalMin":70,"spice":2,"batch":true,"ingredients":[{"key":"chicken","qty":1200},{"key":"curry","qty":30},{"key":"potato","qty":500},{"key":"onion","qty":200},{"key":"garlic","qty":15},{"key":"thyme","qty":3},{"key":"scotch","qty":5},{"key":"allspice","qty":3},{"key":"oil","qty":40},{"key":"rice","qty":400}],"steps":["Rub {chicken} with half the {curry}, minced {garlic}, {thyme}, {allspice} and salt. Rest 20 minutes, or overnight [t20].","Toast the remaining curry in hot {oil} for 1 minute until fragrant, then brown the chicken.","Add sliced {onion}, a whole {scotch} and 500 ml water. Cover and simmer [t30].","Add cubed {potato} and simmer uncovered until the sauce thickens and the chicken is cooked through [t15]. Serve with {rice}."],"source":{"type":"library"},"archetype":"braised-chicken-in-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'e09cf848-8624-4f38-a641-4fb88997ff54', array[]::text[], '[]'::jsonb, 25, 45, 4),
  ('jm_jerk', 'jm-jerk', 'Jerk Chicken with Rice & Peas', null, array['Jamaica']::text[], array['d']::text[], '{"id":"jm_jerk","name":"Jerk Chicken with Rice & Peas","countries":["Jamaica"],"meals":["d"],"activeMin":25,"totalMin":75,"spice":3,"batch":true,"ingredients":[{"key":"chicken","qty":1000},{"key":"jerkpaste","qty":80},{"key":"rice","qty":500},{"key":"kidneybeans","qty":400},{"key":"coconutmilk","qty":400},{"key":"scallion","qty":60},{"key":"thyme","qty":3},{"key":"allspice","qty":3},{"key":"scotch","qty":5}],"steps":["Rub {chicken} with {jerkpaste}; marinate at least 30 minutes (overnight is best) [t30].","Roast at 220 °C until charred at the edges and cooked through [t35].","Rice and peas: bring {coconutmilk}, the liquid from {kidneybeans} topped up with water to 1 L, {thyme}, {allspice}, crushed {scallion} and a whole {scotch} to a simmer.","Add rinsed {rice} and the beans, cover and cook on low until fluffy [t25]. Remove the scotch bonnet before serving."],"source":{"type":"library"},"archetype":"smoky-spiced-chicken"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '5391d651-d964-46a0-a5ea-3570271fd8ba', array[]::text[], '[]'::jsonb, 25, 50, 4),
  ('jm_porridge', 'jm-porridge', 'Cornmeal Porridge', null, array['Jamaica']::text[], array['b']::text[], '{"id":"jm_porridge","name":"Cornmeal Porridge","countries":["Jamaica"],"meals":["b"],"activeMin":10,"totalMin":20,"spice":0,"batch":false,"ingredients":[{"key":"cornmeal","qty":200},{"key":"coconutmilk","qty":400},{"key":"milk","qty":600},{"key":"nutmeg","qty":2},{"key":"cinnamon","qty":2},{"key":"sugar","qty":60}],"steps":["Whisk {cornmeal} into 500 ml cold water until no lumps remain.","Bring {milk} and {coconutmilk} to a simmer, then whisk in the cornmeal mixture.","Cook on low, stirring often, until thick and smooth [t12].","Sweeten with {sugar} and finish with {nutmeg} and {cinnamon}."],"source":{"type":"library"},"archetype":"maize-porridge-and-swallow"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '9381f61f-9bda-4476-aef4-376d2e8528b5', array[]::text[], '[]'::jsonb, 10, 10, 4),
  ('jm_callaloo', 'jm-callaloo', 'Steamed Callaloo with Fried Dumplings', null, array['Jamaica']::text[], array['b']::text[], '{"id":"jm_callaloo","name":"Steamed Callaloo with Fried Dumplings","countries":["Jamaica"],"meals":["b"],"activeMin":25,"totalMin":35,"spice":1,"batch":false,"ingredients":[{"key":"kale","qty":400},{"key":"onion","qty":100},{"key":"tomato","qty":150},{"key":"scotch","qty":5},{"key":"butter","qty":30},{"key":"flour","qty":300},{"key":"oil","qty":150},{"key":"garlic","qty":10}],"steps":["Mix {flour} with a pinch of salt and about 150 ml water into a firm dough. Shape into small flat rounds.","Fry the dumplings in {oil} over medium heat until golden and hollow-sounding [t10].","Strip and slice {kale} (stands in for callaloo). Melt {butter}, soften {onion}, {garlic} and {scotch}, then add {tomato}.","Add the greens with a splash of water, cover and steam until tender [t8]."],"source":{"type":"library"},"archetype":"leafy-green-stew"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'd0af582e-487b-48a9-a842-27dbf1f8d9c3', array[]::text[], '[]'::jsonb, 25, 10, 4),
  ('tt_chana', 'tt-chana', 'Curry Chana & Aloo with Roti', null, array['Trinidad and Tobago']::text[], array['l', 'd']::text[], '{"id":"tt_chana","name":"Curry Chana & Aloo with Roti","countries":["Trinidad and Tobago"],"meals":["l","d"],"activeMin":20,"totalMin":40,"spice":2,"batch":true,"ingredients":[{"key":"chickpeas","qty":800},{"key":"potato","qty":500},{"key":"onion","qty":150},{"key":"garlic","qty":15},{"key":"curry","qty":20},{"key":"cumin","qty":5},{"key":"oil","qty":40},{"key":"flatbread","qty":400},{"key":"cilantro","qty":20},{"key":"scotch","qty":5}],"steps":["Mix {curry} and {cumin} with a little water into a paste. Fry in {oil} until it darkens [t2].","Add chopped {onion} and {garlic}, then cubed {potato}, drained {chickpeas}, {scotch} and 500 ml water.","Simmer until the potatoes break down and thicken the sauce [t20]. Mash a few chickpeas against the pot.","Stir in {cilantro} (stands in for shado beni) and serve with warm {flatbread}."],"source":{"type":"library"},"archetype":"stewed-legumes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', array[]::text[], '[]'::jsonb, 20, 20, 4),
  ('ht_griot', 'ht-griot', 'Griot with Pikliz', null, array['Haiti']::text[], array['d']::text[], '{"id":"ht_griot","name":"Griot with Pikliz","countries":["Haiti"],"meals":["d"],"activeMin":25,"totalMin":100,"spice":2,"batch":true,"ingredients":[{"key":"pork","qty":1000},{"key":"orange","qty":300},{"key":"lime","qty":140},{"key":"onion","qty":150},{"key":"garlic","qty":20},{"key":"scotch","qty":10},{"key":"thyme","qty":3},{"key":"cabbage","qty":300},{"key":"carrot","qty":150},{"key":"vinegar","qty":250},{"key":"oil","qty":60},{"key":"rice","qty":400}],"steps":["Pikliz: shred {cabbage} and {carrot}, slice {scotch*0.5}, pack into a jar and cover with {vinegar} and a pinch of salt. Chill.","Cube {pork} and marinate with the juice of {orange} and {lime}, {garlic}, {onion}, {thyme} and the remaining scotch [t30].","Simmer the pork in its marinade plus water to cover until tender [t50]. Drain.","Fry the pork in {oil} until crisp at the edges [t10]. Serve with {rice} and pikliz."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 75, 4),
  ('do_mangu', 'do-mangu', 'Mangú with Eggs & Pickled Onions', null, array['Dominican Republic']::text[], array['b']::text[], '{"id":"do_mangu","name":"Mangú with Eggs & Pickled Onions","countries":["Dominican Republic"],"meals":["b"],"activeMin":20,"totalMin":35,"spice":0,"batch":false,"ingredients":[{"key":"greenplantain","qty":1000},{"key":"redonion","qty":200},{"key":"vinegar","qty":40},{"key":"eggs","qty":4},{"key":"butter","qty":40},{"key":"oil","qty":20}],"steps":["Slice {redonion} thinly and soak in {vinegar} with a pinch of salt.","Peel {greenplantain}, cut into chunks and boil until very soft [t20].","Mash with {butter} and a splash of the cooking water until smooth.","Fry {eggs} in {oil} until the whites are fully set. Top the mangú with eggs and pickled onions."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 15, 4),
  ('cu_moros', 'cu-moros', 'Moros y Cristianos', null, array['Cuba']::text[], array['l', 'd']::text[], '{"id":"cu_moros","name":"Moros y Cristianos","countries":["Cuba"],"meals":["l","d"],"activeMin":20,"totalMin":45,"spice":0,"batch":true,"ingredients":[{"key":"blackbeans","qty":800},{"key":"rice","qty":400},{"key":"onion","qty":150},{"key":"redpepper","qty":150},{"key":"garlic","qty":15},{"key":"cumin","qty":4},{"key":"oregano","qty":2},{"key":"bay","qty":2},{"key":"oliveoil","qty":40},{"key":"stock","qty":600}],"steps":["Sofrito: cook chopped {onion}, {redpepper} and {garlic} in {oliveoil} until soft [t8].","Add {cumin}, {oregano} and {bay}, then {rice}; stir 1 minute to toast.","Add {blackbeans} with their liquid and {stock}. Cover and simmer on low [t20].","Rest 5 minutes off the heat, then fluff."],"source":{"type":"library"},"archetype":"legume-and-rice-staple"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '176638a3-c660-493f-ae74-3963824c461f', array[]::text[], '[]'::jsonb, 20, 25, 4),
  ('mx_rancheros', 'mx-rancheros', 'Huevos Rancheros', null, array['Mexico']::text[], array['b']::text[], '{"id":"mx_rancheros","name":"Huevos Rancheros","countries":["Mexico"],"meals":["b"],"activeMin":20,"totalMin":25,"spice":2,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"tortilla","qty":300},{"key":"tomato","qty":400},{"key":"onion","qty":100},{"key":"jalapeno","qty":30},{"key":"blackbeans","qty":400},{"key":"avocado","qty":300},{"key":"cilantro","qty":20},{"key":"cheese","qty":100},{"key":"oil","qty":30}],"steps":["Char {tomato}, {onion} and {jalapeno} in a dry pan [t6], then blend into a salsa and simmer 5 minutes.","Warm {blackbeans} and mash lightly.","Warm {tortilla} in a dry pan. Fry {eggs} in {oil} until the whites are set.","Layer tortillas, beans, egg and salsa. Top with sliced {avocado}, crumbled {cheese} and {cilantro}."],"source":{"type":"library"},"archetype":"eggs-in-tomato-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'bf173926-2a08-48b1-afe3-dd73b638e676', array[]::text[], '[]'::jsonb, 20, 5, 4),
  ('mx_tinga', 'mx-tinga', 'Chicken Tinga Tacos', null, array['Mexico']::text[], array['l', 'd']::text[], '{"id":"mx_tinga","name":"Chicken Tinga Tacos","countries":["Mexico"],"meals":["l","d"],"activeMin":25,"totalMin":45,"spice":2,"batch":true,"ingredients":[{"key":"chicken","qty":800},{"key":"chipotle","qty":40},{"key":"tomato","qty":400},{"key":"onion","qty":200},{"key":"garlic","qty":10},{"key":"tortilla","qty":400},{"key":"cabbage","qty":200},{"key":"lime","qty":140},{"key":"avocado","qty":150},{"key":"oil","qty":20}],"steps":["Poach {chicken} in salted water until cooked through [t20]. Shred.","Blend {tomato}, {chipotle} and {garlic}. Soften sliced {onion} in {oil}, add the sauce and simmer [t8].","Fold in the chicken and simmer until saucy.","Serve in warm {tortilla} with shredded {cabbage}, {avocado} and wedges of {lime}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 20, 4),
  ('pe_lomo', 'pe-lomo', 'Lomo Saltado', null, array['Peru']::text[], array['d']::text[], '{"id":"pe_lomo","name":"Lomo Saltado","countries":["Peru"],"meals":["d"],"activeMin":30,"totalMin":40,"spice":1,"batch":false,"ingredients":[{"key":"sirloin","qty":700},{"key":"redonion","qty":300},{"key":"tomato","qty":300},{"key":"soysauce","qty":45},{"key":"vinegar","qty":15},{"key":"jalapeno","qty":20},{"key":"potato","qty":700},{"key":"rice","qty":400},{"key":"cilantro","qty":20},{"key":"oil","qty":100}],"steps":["Cook {rice}. Cut {potato} into fries and oven-bake at 220 °C until crisp [t30].","Slice {sirloin} into strips. Sear in very hot {oil*0.3} in batches until browned [t3]. Remove.","Stir-fry wedges of {redonion} and {jalapeno} for 1 minute, add {tomato} wedges, {soysauce} and {vinegar}.","Return the beef, toss with the fries and {cilantro}. Serve with rice."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 30, 10, 4),
  ('br_moqueca', 'br-moqueca', 'Moqueca Baiana', null, array['Brazil']::text[], array['d']::text[], '{"id":"br_moqueca","name":"Moqueca Baiana","countries":["Brazil"],"meals":["d"],"activeMin":25,"totalMin":40,"spice":1,"batch":false,"ingredients":[{"key":"whitefish","qty":800},{"key":"coconutmilk","qty":400},{"key":"tomato","qty":300},{"key":"onion","qty":200},{"key":"redpepper","qty":200},{"key":"lime","qty":140},{"key":"garlic","qty":10},{"key":"palmoil","qty":30},{"key":"cilantro","qty":20},{"key":"rice","qty":400}],"steps":["Marinate {whitefish} with the juice of {lime}, {garlic} and salt [t15].","Layer sliced {onion}, {redpepper} and {tomato} in a wide pot and lay the fish on top.","Pour over {coconutmilk} and {palmoil}. Cover and simmer gently until the fish flakes [t15].","Scatter with {cilantro}. Serve with {rice}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 15, 4),
  ('co_arepas', 'co-arepas', 'Arepas with Huevos Pericos', null, array['Colombia']::text[], array['b']::text[], '{"id":"co_arepas","name":"Arepas with Huevos Pericos","countries":["Colombia"],"meals":["b"],"activeMin":25,"totalMin":35,"spice":0,"batch":false,"ingredients":[{"key":"masarepa","qty":300},{"key":"eggs","qty":8},{"key":"tomato","qty":200},{"key":"scallion","qty":60},{"key":"butter","qty":30},{"key":"cheese","qty":100}],"steps":["Mix {masarepa} with 400 ml warm water and salt into a soft dough. Rest [t5].","Shape 8 patties and cook in a dry pan until crusty on both sides [t12].","Melt {butter}, cook chopped {scallion} and {tomato} for 3 minutes.","Add beaten {eggs} and scramble until fully set. Split the arepas and fill with eggs and {cheese}."],"source":{"type":"library"},"archetype":"maize-porridge-and-swallow"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '9381f61f-9bda-4476-aef4-376d2e8528b5', array[]::text[], '[]'::jsonb, 25, 10, 4),
  ('ma_tagine', 'ma-tagine', 'Chickpea & Vegetable Tagine with Couscous', null, array['Morocco']::text[], array['l', 'd']::text[], '{"id":"ma_tagine","name":"Chickpea & Vegetable Tagine with Couscous","countries":["Morocco"],"meals":["l","d"],"activeMin":25,"totalMin":55,"spice":1,"batch":true,"ingredients":[{"key":"chickpeas","qty":800},{"key":"carrot","qty":300},{"key":"zucchini","qty":300},{"key":"sweetpotato","qty":500},{"key":"onion","qty":200},{"key":"garlic","qty":15},{"key":"passata","qty":400},{"key":"rasel","qty":15},{"key":"apricot","qty":100},{"key":"couscous","qty":400},{"key":"cilantro","qty":20},{"key":"oliveoil","qty":40}],"steps":["Soften chopped {onion} and {garlic} in {oliveoil} [t5]. Add {rasel} and cook 1 minute.","Add chunks of {carrot} and {sweetpotato}, {passata} and 400 ml water. Simmer [t15].","Add {zucchini}, drained {chickpeas} and {apricot}. Simmer until all the vegetables are tender [t15].","Pour 1¼ times its volume of boiling water over {couscous}, cover 5 minutes, then fluff. Serve with {cilantro}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 30, 4),
  ('tn_shakshuka', 'tn-shakshuka', 'Shakshuka', null, array['Tunisia']::text[], array['b', 'l']::text[], '{"id":"tn_shakshuka","name":"Shakshuka","countries":["Tunisia"],"meals":["b","l"],"activeMin":15,"totalMin":30,"spice":2,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"passata","qty":700},{"key":"redpepper","qty":300},{"key":"onion","qty":150},{"key":"garlic","qty":10},{"key":"cumin","qty":4},{"key":"paprika","qty":4},{"key":"bread","qty":400},{"key":"parsley","qty":20},{"key":"oliveoil","qty":30}],"steps":["Soften sliced {onion} and {redpepper} in {oliveoil} [t8]. Add {garlic}, {cumin} and {paprika}.","Pour in {passata} and simmer until thick [t10].","Make 8 wells and crack in {eggs}. Cover and cook until the whites are fully set [t7].","Scatter with {parsley} and serve with {bread}."],"source":{"type":"library"},"archetype":"eggs-in-tomato-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'bf173926-2a08-48b1-afe3-dd73b638e676', array[]::text[], '[]'::jsonb, 15, 15, 4),
  ('eg_koshari', 'eg-koshari', 'Koshari', null, array['Egypt']::text[], array['l', 'd']::text[], '{"id":"eg_koshari","name":"Koshari","countries":["Egypt"],"meals":["l","d"],"activeMin":30,"totalMin":50,"spice":1,"batch":true,"ingredients":[{"key":"lentils","qty":250},{"key":"rice","qty":300},{"key":"pasta","qty":250},{"key":"chickpeas","qty":400},{"key":"onion","qty":400},{"key":"passata","qty":500},{"key":"garlic","qty":15},{"key":"vinegar","qty":30},{"key":"cumin","qty":4},{"key":"chilipowder","qty":2},{"key":"oil","qty":80}],"steps":["Slice {onion} thinly and fry in {oil} until deep brown and crisp [t15]. Keep the oil.","Boil {lentils} until just tender [t15]; cook {pasta} separately.","Cook {rice} with the lentils and a spoon of the onion oil, covered on low [t18].","Simmer {passata} with {garlic}, {cumin}, {chilipowder} and {vinegar} [t10].","Layer rice and lentils, pasta and {chickpeas}; spoon over the sauce and top with the crispy onions."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 30, 20, 4),
  ('lb_mujaddara', 'lb-mujaddara', 'Mujaddara with Cucumber Yogurt', null, array['Lebanon']::text[], array['l', 'd']::text[], '{"id":"lb_mujaddara","name":"Mujaddara with Cucumber Yogurt","countries":["Lebanon"],"meals":["l","d"],"activeMin":20,"totalMin":45,"spice":0,"batch":true,"ingredients":[{"key":"lentils","qty":300},{"key":"rice","qty":250},{"key":"onion","qty":600},{"key":"oliveoil","qty":80},{"key":"cumin","qty":4},{"key":"cucumber","qty":300},{"key":"tomato","qty":300},{"key":"yogurt","qty":300},{"key":"mint","qty":10}],"steps":["Slice {onion} and cook slowly in {oliveoil} until dark golden [t20]. Remove half for the topping.","Add {lentils}, {cumin} and 1 L water to the pot; simmer [t10].","Stir in {rice}, cover and cook on low until tender [t20].","Mix grated {cucumber*0.5} with {yogurt} and {mint}. Dice the rest with {tomato} for a salad."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 25, 4),
  ('lb_manakish', 'lb-manakish', 'Za''atar Manakish Breakfast Plate', null, array['Lebanon']::text[], array['b']::text[], '{"id":"lb_manakish","name":"Za''atar Manakish Breakfast Plate","countries":["Lebanon"],"meals":["b"],"activeMin":10,"totalMin":15,"spice":0,"batch":false,"ingredients":[{"key":"flatbread","qty":400},{"key":"zaatar","qty":40},{"key":"oliveoil","qty":60},{"key":"cucumber","qty":300},{"key":"tomato","qty":250},{"key":"yogurt","qty":250},{"key":"mint","qty":10}],"steps":["Mix {zaatar} with {oliveoil} into a loose paste.","Spread over {flatbread} and bake at 220 °C until the edges crisp [t6].","Serve with sliced {cucumber}, {tomato}, {yogurt} (or labneh) and {mint}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 10, 5, 4),
  ('tr_mercimek', 'tr-mercimek', 'Red Lentil Soup (Mercimek Çorbası)', null, array['Turkey']::text[], array['l']::text[], '{"id":"tr_mercimek","name":"Red Lentil Soup (Mercimek Çorbası)","countries":["Turkey"],"meals":["l"],"activeMin":15,"totalMin":35,"spice":0,"batch":true,"ingredients":[{"key":"lentils","qty":300},{"key":"onion","qty":150},{"key":"carrot","qty":150},{"key":"potato","qty":150},{"key":"tomatopaste","qty":30},{"key":"cumin","qty":4},{"key":"paprika","qty":3},{"key":"lemon","qty":100},{"key":"butter","qty":30},{"key":"stock","qty":1500}],"steps":["Soften chopped {onion} and {carrot} in {butter} [t5]. Stir in {tomatopaste} and {cumin}.","Add rinsed {lentils}, diced {potato} and {stock}. Simmer until everything is soft [t25].","Blend smooth. Finish with {paprika} sizzled in a little butter and a squeeze of {lemon}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 20, 4),
  ('ir_kuku', 'ir-kuku', 'Kuku Sabzi (Herb Frittata)', null, array['Iran']::text[], array['b', 'l']::text[], '{"id":"ir_kuku","name":"Kuku Sabzi (Herb Frittata)","countries":["Iran"],"meals":["b","l"],"activeMin":20,"totalMin":40,"spice":0,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"parsley","qty":120},{"key":"cilantro","qty":120},{"key":"dill","qty":30},{"key":"scallion","qty":100},{"key":"walnuts","qty":50},{"key":"turmeric","qty":2},{"key":"oil","qty":40},{"key":"flatbread","qty":400}],"steps":["Very finely chop {parsley}, {cilantro}, {dill} and {scallion} — this is a herb cake bound by egg, not the other way round.","Beat {eggs} with {turmeric} and salt; fold in the herbs and chopped {walnuts}.","Pour into a hot pan with {oil}, cover and cook on low [t15]. Flip (or finish under the grill) until set in the centre [t5].","Cut into wedges and serve with {flatbread}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 20, 4),
  ('sa_machboos', 'sa-machboos', 'Chicken Machboos', null, array['Saudi Arabia']::text[], array['d']::text[], '{"id":"sa_machboos","name":"Chicken Machboos","countries":["Saudi Arabia"],"meals":["d"],"activeMin":25,"totalMin":70,"spice":1,"batch":true,"ingredients":[{"key":"chicken","qty":1000},{"key":"rice","qty":500},{"key":"onion","qty":200},{"key":"tomato","qty":200},{"key":"lime","qty":70},{"key":"baharat","qty":12},{"key":"garlic","qty":15},{"key":"cinnamon","qty":2},{"key":"cardamom","qty":2},{"key":"oil","qty":40},{"key":"stock","qty":1000}],"steps":["Brown {chicken} in {oil}; remove. Soften {onion} and {garlic}, then add {baharat}, {cinnamon} and {cardamom}.","Add chopped {tomato}, a pierced whole {lime} and {stock}. Return the chicken and simmer [t30].","Lift out the chicken and roast at 220 °C to crisp the skin [t15].","Add rinsed {rice} to the broth; cover and cook on low [t20]. Serve the chicken over the rice."],"source":{"type":"library"},"archetype":"braised-chicken-in-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'e09cf848-8624-4f38-a641-4fb88997ff54', array[]::text[], '[]'::jsonb, 25, 45, 4),
  ('in_dal', 'in-dal', 'Dal Tadka with Rice', null, array['India']::text[], array['l', 'd']::text[], '{"id":"in_dal","name":"Dal Tadka with Rice","countries":["India"],"meals":["l","d"],"activeMin":20,"totalMin":40,"spice":1,"batch":true,"ingredients":[{"key":"lentils","qty":350},{"key":"onion","qty":150},{"key":"tomato","qty":200},{"key":"garlic","qty":15},{"key":"ginger","qty":15},{"key":"cumin","qty":4},{"key":"turmeric","qty":2},{"key":"chilipowder","qty":2},{"key":"oil","qty":40},{"key":"rice","qty":400},{"key":"cilantro","qty":20}],"steps":["Rinse {lentils}; simmer with {turmeric} and 1 L water until soft [t25]. Cook {rice}.","Fry {cumin} in {oil} until it crackles. Add {onion}, {garlic} and {ginger}; cook until golden [t6].","Add {tomato} and {chilipowder}; cook until jammy, then pour over the dal.","Finish with {cilantro}."],"source":{"type":"library"},"archetype":"stewed-legumes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', array[]::text[], '[]'::jsonb, 20, 20, 4),
  ('in_poha', 'in-poha', 'Kanda Poha', null, array['India']::text[], array['b']::text[], '{"id":"in_poha","name":"Kanda Poha","countries":["India"],"meals":["b"],"activeMin":15,"totalMin":20,"spice":1,"batch":false,"ingredients":[{"key":"poha","qty":300},{"key":"onion","qty":150},{"key":"potato","qty":200},{"key":"peanuts","qty":60},{"key":"mustardseed","qty":4},{"key":"turmeric","qty":2},{"key":"lemon","qty":50},{"key":"cilantro","qty":20},{"key":"oil","qty":30},{"key":"greenchili","qty":10}],"steps":["Rinse {poha} in a sieve under running water for 20 seconds; drain and rest.","Fry {peanuts} in {oil} until golden; remove. Add {mustardseed} until they pop.","Cook diced {potato} with {turmeric}, covered, until tender [t8]. Add {onion} and {greenchili} for 2 minutes.","Fold in the poha, peanuts and salt; steam covered 2 minutes. Finish with {lemon} and {cilantro}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 5, 4),
  ('in_palak', 'in-palak', 'Palak Paneer with Roti', null, array['India']::text[], array['d']::text[], '{"id":"in_palak","name":"Palak Paneer with Roti","countries":["India"],"meals":["d"],"activeMin":25,"totalMin":40,"spice":1,"batch":false,"ingredients":[{"key":"spinach","qty":600},{"key":"paneer","qty":400},{"key":"onion","qty":150},{"key":"tomato","qty":150},{"key":"garlic","qty":15},{"key":"ginger","qty":15},{"key":"garammasala","qty":5},{"key":"cumin","qty":3},{"key":"oil","qty":40},{"key":"flatbread","qty":400}],"steps":["Blanch {spinach} for 1 minute [t1], plunge into iced water and blend smooth.","Fry {cumin} in {oil}, add {onion}, {garlic} and {ginger}; cook until golden [t8]. Add {tomato} and cook down.","Stir in the spinach purée and {garammasala}; simmer 5 minutes.","Add cubed {paneer} and warm through. Serve with {flatbread}."],"source":{"type":"library"},"archetype":"leafy-green-stew"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'd0af582e-487b-48a9-a842-27dbf1f8d9c3', array[]::text[], '[]'::jsonb, 25, 15, 4),
  ('in_omelette', 'in-omelette', 'Masala Omelette with Paratha', null, array['India']::text[], array['b']::text[], '{"id":"in_omelette","name":"Masala Omelette with Paratha","countries":["India"],"meals":["b"],"activeMin":15,"totalMin":15,"spice":1,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"onion","qty":100},{"key":"tomato","qty":100},{"key":"greenchili","qty":10},{"key":"cilantro","qty":20},{"key":"oil","qty":20},{"key":"flatbread","qty":400}],"steps":["Finely chop {onion}, {tomato}, {greenchili} and {cilantro}; beat into {eggs} with salt.","Cook in batches in {oil} until just set [t3]; fold.","Serve with warm {flatbread}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 0, 4),
  ('pk_karahi', 'pk-karahi', 'Chicken Karahi', null, array['Pakistan']::text[], array['d']::text[], '{"id":"pk_karahi","name":"Chicken Karahi","countries":["Pakistan"],"meals":["d"],"activeMin":30,"totalMin":45,"spice":3,"batch":false,"ingredients":[{"key":"chicken","qty":1000},{"key":"tomato","qty":600},{"key":"ginger","qty":40},{"key":"garlic","qty":20},{"key":"greenchili","qty":20},{"key":"yogurt","qty":150},{"key":"garammasala","qty":5},{"key":"oil","qty":60},{"key":"flatbread","qty":400},{"key":"cilantro","qty":20}],"steps":["Sear {chicken} in {oil} over high heat [t6].","Add {garlic} and half the {ginger}; stir 1 minute. Add halved {tomato}, cover and cook until soft [t10]. Pull out the skins.","Cook uncovered, stirring, until the oil separates and the chicken is cooked through [t10].","Stir in {yogurt}, {garammasala}, sliced {greenchili} and the rest of the ginger in thin strips. Garnish with {cilantro}; serve with {flatbread}."],"source":{"type":"library"},"archetype":"braised-chicken-in-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'e09cf848-8624-4f38-a641-4fb88997ff54', array[]::text[], '[]'::jsonb, 30, 15, 4),
  ('lk_dhal', 'lk-dhal', 'Coconut Dhal with Pol Sambol', null, array['Sri Lanka']::text[], array['l']::text[], '{"id":"lk_dhal","name":"Coconut Dhal with Pol Sambol","countries":["Sri Lanka"],"meals":["l"],"activeMin":15,"totalMin":30,"spice":2,"batch":false,"ingredients":[{"key":"lentils","qty":300},{"key":"coconutmilk","qty":400},{"key":"onion","qty":150},{"key":"garlic","qty":10},{"key":"turmeric","qty":2},{"key":"desiccated","qty":100},{"key":"lime","qty":70},{"key":"chilipowder","qty":3},{"key":"rice","qty":300},{"key":"oil","qty":20}],"steps":["Simmer {lentils} with {turmeric}, half the onion and 600 ml water until soft [t15].","Stir in {coconutmilk}; simmer 5 minutes.","Fry {garlic} and the remaining {onion*0.5} in {oil}; pour over the dhal. Cook {rice}.","Pol sambol: rub {desiccated} with {chilipowder}, salt and the juice of {lime}."],"source":{"type":"library"},"archetype":"stewed-legumes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', array[]::text[], '[]'::jsonb, 15, 15, 4),
  ('cn_congee', 'cn-congee', 'Ginger Chicken Congee', null, array['China']::text[], array['b', 'l']::text[], '{"id":"cn_congee","name":"Ginger Chicken Congee","countries":["China"],"meals":["b","l"],"activeMin":10,"totalMin":80,"spice":0,"batch":true,"ingredients":[{"key":"rice","qty":250},{"key":"chicken","qty":400},{"key":"ginger","qty":40},{"key":"scallion","qty":60},{"key":"soysauce","qty":30},{"key":"sesameoil","qty":10},{"key":"stock","qty":2000}],"steps":["Simmer {rice} with {stock}, sliced {ginger} and whole {chicken}, partly covered [t20].","Lift out the chicken once cooked through; shred it.","Keep simmering, stirring now and then, until silky [t50].","Top with the chicken, {scallion}, {soysauce} and {sesameoil}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 10, 70, 4),
  ('cn_tomatoegg', 'cn-tomatoegg', 'Tomato & Egg Stir-fry with Rice', null, array['China']::text[], array['l', 'd']::text[], '{"id":"cn_tomatoegg","name":"Tomato & Egg Stir-fry with Rice","countries":["China"],"meals":["l","d"],"activeMin":15,"totalMin":25,"spice":0,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"tomato","qty":800},{"key":"scallion","qty":60},{"key":"sugar","qty":10},{"key":"soysauce","qty":15},{"key":"oil","qty":40},{"key":"rice","qty":400}],"steps":["Cook {rice}. Beat {eggs} with salt.","Scramble the eggs in half the {oil} until just set; remove.","Fry {tomato} wedges in the remaining oil with {sugar} and {soysauce} until saucy [t5].","Return the eggs, fold together and top with {scallion}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 10, 4),
  ('jp_salmon', 'jp-salmon', 'Miso-Glazed Salmon with Rice & Bok Choy', null, array['Japan']::text[], array['d']::text[], '{"id":"jp_salmon","name":"Miso-Glazed Salmon with Rice & Bok Choy","countries":["Japan"],"meals":["d"],"activeMin":15,"totalMin":30,"spice":0,"batch":false,"ingredients":[{"key":"salmon","qty":600},{"key":"miso","qty":60},{"key":"mirin","qty":30},{"key":"rice","qty":400},{"key":"bokchoy","qty":400},{"key":"sesameseeds","qty":10},{"key":"soysauce","qty":15}],"steps":["Cook {rice}. Mix {miso} and {mirin}; brush over {salmon}.","Grill or bake at 220 °C until glazed and the fish flakes [t10].","Steam halved {bokchoy} [t3]; dress with {soysauce}.","Sprinkle {sesameseeds} over everything."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 15, 4),
  ('jp_breakfast', 'jp-breakfast', 'Tamagoyaki & Miso Soup with Rice', null, array['Japan']::text[], array['b']::text[], '{"id":"jp_breakfast","name":"Tamagoyaki & Miso Soup with Rice","countries":["Japan"],"meals":["b"],"activeMin":20,"totalMin":25,"spice":0,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"miso","qty":50},{"key":"tofu","qty":300},{"key":"scallion","qty":40},{"key":"rice","qty":300},{"key":"sugar","qty":10},{"key":"soysauce","qty":10},{"key":"oil","qty":10}],"steps":["Cook {rice}.","Beat {eggs} with {sugar} and {soysauce}. Cook in thin layers in a pan wiped with {oil}, rolling each layer [t8].","Bring 1 L water to a bare simmer, whisk in {miso} (don''t boil), add cubed {tofu} and {scallion}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 5, 4),
  ('kr_bibimbap', 'kr-bibimbap', 'Bibimbap', null, array['South Korea']::text[], array['l', 'd']::text[], '{"id":"kr_bibimbap","name":"Bibimbap","countries":["South Korea"],"meals":["l","d"],"activeMin":35,"totalMin":45,"spice":2,"batch":false,"ingredients":[{"key":"rice","qty":400},{"key":"beefmince","qty":400},{"key":"spinach","qty":300},{"key":"carrot","qty":200},{"key":"beansprouts","qty":200},{"key":"eggs","qty":4},{"key":"gochujang","qty":60},{"key":"sesameoil","qty":20},{"key":"garlic","qty":10},{"key":"soysauce","qty":30}],"steps":["Cook {rice}.","Brown {beefmince} with {garlic} and {soysauce} until no pink remains [t6].","Blanch {spinach} and {beansprouts} separately [t1]; season each with a little {sesameoil}. Stir-fry thin strips of {carrot} [t2].","Fry {eggs} until the whites are set.","Arrange everything over the rice and serve with {gochujang}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 35, 10, 4),
  ('th_green', 'th-green', 'Green Curry with Chicken', null, array['Thailand']::text[], array['d']::text[], '{"id":"th_green","name":"Green Curry with Chicken","countries":["Thailand"],"meals":["d"],"activeMin":20,"totalMin":35,"spice":2,"batch":false,"ingredients":[{"key":"chicken","qty":700},{"key":"greencurrypaste","qty":60},{"key":"coconutmilk","qty":800},{"key":"eggplant","qty":300},{"key":"greenbeans","qty":200},{"key":"fishsauce","qty":30},{"key":"sugar","qty":10},{"key":"basil","qty":20},{"key":"rice","qty":400},{"key":"oil","qty":15}],"steps":["Cook {rice}. Fry {greencurrypaste} in {oil} with a few spoons of the thick top of the {coconutmilk} until fragrant [t3].","Add sliced {chicken}; cook 3 minutes, then the rest of the coconut milk.","Add {eggplant} and {greenbeans}; simmer until the chicken is cooked through [t12].","Season with {fishsauce} and {sugar}; tear in {basil}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 15, 4),
