  ('ph_adobo', 'ph-adobo', 'Chicken Adobo', null, array['Philippines']::text[], array['d']::text[], '{"id":"ph_adobo","name":"Chicken Adobo","countries":["Philippines"],"meals":["d"],"activeMin":15,"totalMin":55,"spice":0,"batch":true,"ingredients":[{"key":"chicken","qty":1200},{"key":"soysauce","qty":120},{"key":"vinegar","qty":120},{"key":"garlic","qty":40},{"key":"bay","qty":3},{"key":"blackpepper","qty":4},{"key":"rice","qty":500},{"key":"oil","qty":20}],"steps":["Combine {chicken}, {soysauce}, smashed {garlic}, {bay} and {blackpepper}; rest 20 minutes [t20].","Brown the chicken in {oil}, add the marinade and {vinegar}. Don''t stir until it boils — that mellows the vinegar.","Simmer covered until cooked through [t25], then uncovered to reduce to a glossy sauce [t10].","Serve with {rice}."],"source":{"type":"library"},"archetype":"braised-chicken-in-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'e09cf848-8624-4f38-a641-4fb88997ff54', array[]::text[], '[]'::jsonb, 15, 40, 4),
  ('id_nasigoreng', 'id-nasigoreng', 'Nasi Goreng', null, array['Indonesia']::text[], array['b', 'l']::text[], '{"id":"id_nasigoreng","name":"Nasi Goreng","countries":["Indonesia"],"meals":["b","l"],"activeMin":20,"totalMin":25,"spice":2,"batch":false,"ingredients":[{"key":"rice","qty":350},{"key":"eggs","qty":4},{"key":"onion","qty":150},{"key":"garlic","qty":10},{"key":"kecapmanis","qty":45},{"key":"chilipowder","qty":3},{"key":"chicken","qty":300},{"key":"cucumber","qty":200},{"key":"oil","qty":40}],"steps":["Use cold cooked rice: cook {rice} the day before, or cook it and spread it on a tray to cool [t20].","Stir-fry thin strips of {chicken} in {oil} until cooked through [t5]. Add {onion}, {garlic} and {chilipowder}.","Add the rice and {kecapmanis}; toss over high heat until hot [t4].","Fry {eggs} until set and serve on top with sliced {cucumber}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 5, 4),
