  ('gr_souvlaki', 'gr-souvlaki', 'Chicken Souvlaki Bowls with Tzatziki', null, array['Greece']::text[], array['l', 'd']::text[], '{"id":"gr_souvlaki","name":"Chicken Souvlaki Bowls with Tzatziki","countries":["Greece"],"meals":["l","d"],"activeMin":25,"totalMin":40,"spice":0,"batch":false,"ingredients":[{"key":"chicken","qty":800},{"key":"lemon","qty":100},{"key":"oregano","qty":3},{"key":"garlic","qty":15},{"key":"yogurt","qty":300},{"key":"cucumber","qty":300},{"key":"tomato","qty":300},{"key":"redonion","qty":100},{"key":"flatbread","qty":400},{"key":"oliveoil","qty":40}],"steps":["Marinate cubed {chicken} with the juice of {lemon}, {oregano}, half the {garlic} and {oliveoil} [t15].","Thread onto skewers and grill or pan-sear until cooked through [t12].","Tzatziki: grate half the {cucumber}, squeeze it dry and mix with {yogurt} and the remaining garlic.","Serve with {flatbread}, chopped {tomato}, the rest of the cucumber and {redonion}."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 15, 4),
