  ('es_tortilla', 'es-tortilla', 'Tortilla Española', null, array['Spain']::text[], array['b', 'l']::text[], '{"id":"es_tortilla","name":"Tortilla Española","countries":["Spain"],"meals":["b","l"],"activeMin":20,"totalMin":45,"spice":0,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"potato","qty":800},{"key":"onion","qty":200},{"key":"oliveoil","qty":200}],"steps":["Thinly slice {potato} and {onion}; poach gently in {oliveoil} until soft, not browned [t20]. Drain, keeping the oil.","Beat {eggs} with salt and fold in the potatoes; rest [t10].","Cook in a little of the oil over medium-low [t8], flip using a plate, and cook until set in the centre [t5]."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 20, 25, 4),
