  ('us_sheetpan', 'us-sheetpan', 'Sheet-Pan Chicken, Sweet Potato & Broccoli', null, array['United States']::text[], array['d']::text[], '{"id":"us_sheetpan","name":"Sheet-Pan Chicken, Sweet Potato & Broccoli","countries":["United States"],"meals":["d"],"activeMin":15,"totalMin":45,"spice":0,"batch":false,"ingredients":[{"key":"chicken","qty":800},{"key":"sweetpotato","qty":800},{"key":"broccoli","qty":500},{"key":"oliveoil","qty":40},{"key":"paprika","qty":4},{"key":"garlic","qty":10}],"steps":["Heat the oven to 220 °C. Toss cubed {sweetpotato} with half the {oliveoil}; roast [t15].","Add {chicken} rubbed with {paprika}, {garlic} and the rest of the oil; roast [t15].","Add {broccoli} florets and roast until charred at the edges and the chicken is cooked through [t12]."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 15, 30, 4),
  ('fx_jerkjollof', 'fx-jerkjollof', 'Jerk Chicken Jollof', null, array['Nigeria', 'Jamaica']::text[], array['d']::text[], '{"id":"fx_jerkjollof","name":"Jerk Chicken Jollof","countries":["Nigeria","Jamaica"],"meals":["d"],"activeMin":30,"totalMin":75,"spice":3,"batch":true,"ingredients":[{"key":"chicken","qty":1000},{"key":"jerkpaste","qty":60},{"key":"rice","qty":500},{"key":"tomato","qty":400},{"key":"redpepper","qty":200},{"key":"scotch","qty":5},{"key":"onion","qty":200},{"key":"tomatopaste","qty":50},{"key":"oil","qty":60},{"key":"stock","qty":700},{"key":"thyme","qty":3},{"key":"allspice","qty":2}],"steps":["Rub {chicken} with {jerkpaste}; marinate [t20]. Roast at 220 °C until cooked through [t35].","Blend {tomato}, {redpepper}, {scotch} and half the {onion}.","Fry the rest of the onion and {tomatopaste} in {oil} until brick red, add the blend, {thyme} and {allspice}; reduce by half [t20].","Add rinsed {rice} and {stock}; cover tightly and steam on low [t30]. Serve under the jerk chicken."],"source":{"type":"library"},"archetype":"tomato-pepper-rice"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '07f3dc87-834f-4d07-a1e5-69aba6aa29e0', array[]::text[], '[]'::jsonb, 30, 45, 4),
  ('fx_plantainshak', 'fx-plantainshak', 'Plantain & Pepper Shakshuka', null, array['Nigeria', 'Tunisia']::text[], array['b', 'l']::text[], '{"id":"fx_plantainshak","name":"Plantain & Pepper Shakshuka","countries":["Nigeria","Tunisia"],"meals":["b","l"],"activeMin":15,"totalMin":30,"spice":2,"batch":false,"ingredients":[{"key":"eggs","qty":8},{"key":"plantain","qty":500},{"key":"passata","qty":500},{"key":"redpepper","qty":200},{"key":"onion","qty":100},{"key":"scotch","qty":5},{"key":"cumin","qty":3},{"key":"oil","qty":40}],"steps":["Fry diced ripe {plantain} in half the {oil} until caramelised; set aside.","Soften {onion}, {redpepper} and {scotch} in the remaining oil with {cumin} [t6]. Add {passata}; simmer [t8].","Stir in the plantain, make wells and crack in {eggs}; cover until the whites are set [t7]."],"source":{"type":"library"},"archetype":"eggs-in-tomato-sauce"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', 'bf173926-2a08-48b1-afe3-dd73b638e676', array[]::text[], '[]'::jsonb, 15, 15, 4),
  ('fx_suya', 'fx-suya', 'Suya Beef Bowls with Pikliz', null, array['Nigeria', 'Haiti']::text[], array['l', 'd']::text[], '{"id":"fx_suya","name":"Suya Beef Bowls with Pikliz","countries":["Nigeria","Haiti"],"meals":["l","d"],"activeMin":25,"totalMin":40,"spice":3,"batch":false,"ingredients":[{"key":"sirloin","qty":700},{"key":"peanuts","qty":60},{"key":"chilipowder","qty":5},{"key":"ginger","qty":10},{"key":"onion","qty":100},{"key":"cabbage","qty":300},{"key":"carrot","qty":150},{"key":"vinegar","qty":200},{"key":"scotch","qty":5},{"key":"rice","qty":400},{"key":"tomato","qty":200}],"steps":["Quick pikliz: shred {cabbage} and {carrot}, add sliced {scotch}, cover with {vinegar} and salt [t15].","Suya spice: grind {peanuts} with {chilipowder}, grated {ginger} and salt. Coat thin strips of {sirloin}.","Sear in a very hot pan until charred [t5]. Cook {rice}.","Serve the beef over rice with sliced {onion}, {tomato} and the pikliz."],"source":{"type":"library"}}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', null, array[]::text[], '[]'::jsonb, 25, 15, 4),
  ('fx_currychana_plantain', 'fx-currychana-plantain', 'Curry Chickpeas with Plantain & Greens', null, array['Trinidad and Tobago', 'Ghana']::text[], array['l', 'd']::text[], '{"id":"fx_currychana_plantain","name":"Curry Chickpeas with Plantain & Greens","countries":["Trinidad and Tobago","Ghana"],"meals":["l","d"],"activeMin":20,"totalMin":35,"spice":2,"batch":true,"ingredients":[{"key":"chickpeas","qty":800},{"key":"plantain","qty":500},{"key":"kale","qty":250},{"key":"onion","qty":150},{"key":"garlic","qty":10},{"key":"curry","qty":15},{"key":"coconutmilk","qty":400},{"key":"scotch","qty":5},{"key":"oil","qty":40},{"key":"rice","qty":400}],"steps":["Toast {curry} in {oil} for 1 minute, then soften {onion}, {garlic} and {scotch} [t5].","Add drained {chickpeas} and {coconutmilk}; simmer [t12]. Cook {rice}.","Fold in sliced {kale} and cook until tender [t4].","Fry sliced ripe {plantain} until golden and serve alongside."],"source":{"type":"library"},"archetype":"stewed-legumes"}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '7a66c93a-1eb7-4bb0-a9d5-b57edbe7365f', array[]::text[], '[]'::jsonb, 20, 15, 4),
  ('ng_rice_and_beans', 'ng-rice-and-beans', 'Nigerian Rice & Beans', null, array['Nigeria']::text[], array['l', 'd']::text[], '{"id":"ng_rice_and_beans","name":"Nigerian Rice & Beans","countries":["Nigeria"],"meals":["l","d"],"activeMin":20,"totalMin":70,"spice":1,"batch":true,"ingredients":[{"key":"honeybeans","qty":300},{"key":"parboiledrice","qty":400},{"key":"palmoil","qty":60},{"key":"onion","qty":150},{"key":"scotch","qty":5},{"key":"crayfish","qty":10},{"key":"stock","qty":300}],"steps":["Pick through {honeybeans} for stones, rinse, and boil in plenty of water until just tender but holding shape [t40]. Don''t salt yet: salt toughens the skins.","Rinse {parboiledrice} until the water runs clear. Add it to the beans with {stock} and enough hot water to cover by 2 cm. Cover and cook on low until the rice is soft and the water is absorbed [t25].","Warm {palmoil} gently (no smoke), fry sliced {onion} and pounded {scotch} until soft and fragrant [t5], then stir in {crayfish}.","Fold the palm-oil sauce through the rice and beans and season with salt. The grains should be separate, the beans creamy inside."],"source":{"type":"library"},"plateRole":"main_one_pot","archetype":"legume-and-rice-staple","flavorTags":["savoury","earthy","palm-oil"],"localNames":[{"name":"Rice and beans","lang":"en","region":"NG"}]}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'main_one_pot', '176638a3-c660-493f-ae74-3963824c461f', array['savoury', 'earthy', 'palm-oil']::text[], '[{"name":"Rice and beans","lang":"en","region":"NG"}]'::jsonb, 20, 50, 4),
  ('ng_dodo', 'ng-dodo', 'Dodo (Fried Ripe Plantain)', null, array['Nigeria']::text[], array['b', 'l', 'd']::text[], '{"id":"ng_dodo","name":"Dodo (Fried Ripe Plantain)","countries":["Nigeria"],"meals":["b","l","d"],"activeMin":10,"totalMin":15,"spice":0,"batch":false,"ingredients":[{"key":"plantain","qty":1000},{"key":"oil","qty":400}],"steps":["Use plantains with mostly black skins: they''re sweetest. Peel {plantain} and cut on the diagonal into 1 cm slices; salt lightly.","Heat {oil} in a deep pan to about 175 °C: a slice should sizzle at once.","Fry in batches without crowding until deep golden with caramelised edges, turning once [t4].","Drain on paper. Dodo is done when the edges are dark amber and the centre is soft and sweet."],"source":{"type":"library"},"plateRole":"sweet_side","archetype":"fried-ripe-plantain","flavorTags":["sweet","caramelised"],"localNames":[{"name":"Dòdò","lang":"yo","region":"NG"}]}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'sweet_side', '3c7fe8f2-eb8d-4cde-a960-5c63622d20dd', array['sweet', 'caramelised']::text[], '[{"name":"Dòdò","lang":"yo","region":"NG"}]'::jsonb, 10, 5, 4),
  ('jm_rice_and_peas', 'jm-rice-and-peas', 'Jamaican Rice & Peas', null, array['Jamaica']::text[], array['l', 'd']::text[], '{"id":"jm_rice_and_peas","name":"Jamaican Rice & Peas","countries":["Jamaica"],"meals":["l","d"],"activeMin":10,"totalMin":40,"spice":1,"batch":true,"ingredients":[{"key":"kidneybeans","qty":400},{"key":"coconutmilk","qty":400},{"key":"rice","qty":400},{"key":"scallion","qty":60},{"key":"garlic","qty":10},{"key":"thyme","qty":3},{"key":"allspice","qty":3},{"key":"scotch","qty":10}],"steps":["Pour {kidneybeans} with their liquid and {coconutmilk} into a pot. Add crushed {garlic}, {thyme}, {allspice} and bruised {scallion}; top up with water to make about 900 ml liquid.","Bring to a simmer, add a whole {scotch} (don''t burst it: it perfumes rather than burns) and season well with salt.","Stir in rinsed {rice}, cover tightly and cook on the lowest heat [t25] until the liquid is absorbed.","Lift out the scotch bonnet and scallion. Fluff with a fork: the rice should be pale pink and fragrant with coconut."],"source":{"type":"library"},"plateRole":"base_starch","archetype":"legume-and-rice-staple","flavorTags":["coconut","allspice","savoury"],"localNames":[{"name":"Rice and peas","lang":"en","region":"JM"}]}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'base_starch', '176638a3-c660-493f-ae74-3963824c461f', array['coconut', 'allspice', 'savoury']::text[], '[{"name":"Rice and peas","lang":"en","region":"JM"}]'::jsonb, 10, 30, 4),
  ('jm_fried_ripe_plantain', 'jm-fried-ripe-plantain', 'Jamaican Fried Ripe Plantain', null, array['Jamaica']::text[], array['b', 'l', 'd']::text[], '{"id":"jm_fried_ripe_plantain","name":"Jamaican Fried Ripe Plantain","countries":["Jamaica"],"meals":["b","l","d"],"activeMin":10,"totalMin":15,"spice":0,"batch":false,"ingredients":[{"key":"plantain","qty":750},{"key":"oil","qty":150}],"steps":["Peel ripe {plantain} (yellow with plenty of black spots) and slice lengthwise or on a long diagonal, about 1 cm thick.","Shallow-fry in {oil} over medium heat, turning once, until both sides are golden brown and glossy [t6].","Drain briefly. Serve warm beside jerk, ackee or rice and peas."],"source":{"type":"library"},"plateRole":"sweet_side","archetype":"fried-ripe-plantain","flavorTags":["sweet","caramelised"]}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'sweet_side', '3c7fe8f2-eb8d-4cde-a960-5c63622d20dd', array['sweet', 'caramelised']::text[], '[]'::jsonb, 10, 5, 4),
  ('jm_jerk_chicken', 'jm-jerk-chicken', 'Jamaican Jerk Chicken', null, array['Jamaica']::text[], array['d']::text[], '{"id":"jm_jerk_chicken","name":"Jamaican Jerk Chicken","countries":["Jamaica"],"meals":["d"],"activeMin":25,"totalMin":90,"spice":3,"batch":true,"ingredients":[{"key":"chicken","qty":1200},{"key":"scallion","qty":100},{"key":"scotch","qty":15},{"key":"allspice","qty":6},{"key":"thyme","qty":3},{"key":"garlic","qty":20},{"key":"ginger","qty":20},{"key":"lime","qty":70},{"key":"soysauce","qty":30},{"key":"sugar","qty":20},{"key":"oil","qty":30}],"steps":["Blend {scallion}, {scotch}, {allspice}, {thyme}, {garlic}, {ginger}, the juice of {lime}, {soysauce}, {sugar} and {oil} into a thick marinade.","Slash {chicken} to the bone, rub the marinade into every cut and marinate at least 2 hours, ideally overnight [t120].","Roast at 200 °C, or grill over medium coals, turning, until charred at the edges and cooked through [t45].","Rest 5 minutes. Jerk is ready when the skin is blistered and dark in places and the juices run clear."],"source":{"type":"library"},"plateRole":"protein_main","archetype":"smoky-spiced-chicken","flavorTags":["smoky","spicy","allspice"]}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'protein_main', '5391d651-d964-46a0-a5ea-3570271fd8ba', array['smoky', 'spicy', 'allspice']::text[], '[]'::jsonb, 25, 65, 4),
  ('in_pazham_pori', 'in-pazham-pori', 'Pazham Pori (Kerala Plantain Fritters)', null, array['India']::text[], array['b']::text[], '{"id":"in_pazham_pori","name":"Pazham Pori (Kerala Plantain Fritters)","countries":["India"],"meals":["b"],"activeMin":15,"totalMin":25,"spice":0,"batch":false,"ingredients":[{"key":"plantain","qty":750},{"key":"flour","qty":150},{"key":"sugar","qty":30},{"key":"turmeric","qty":1},{"key":"oil","qty":500}],"steps":["Whisk {flour}, {sugar}, {turmeric} and a pinch of salt with about 180 ml water into a smooth batter that coats a spoon.","Peel ripe {plantain} (Kerala nendran if you can find it) and slice lengthwise into thin, long strips.","Heat {oil} to about 175 °C. Dip each strip in batter and fry until puffed and golden on both sides [t4].","Drain and serve hot with tea, the way it''s eaten at Kerala tea shops in the evening."],"source":{"type":"library"},"plateRole":"sweet_side","archetype":"fried-ripe-plantain","flavorTags":["sweet","crisp"],"localNames":[{"name":"Ethakka appam","lang":"ml","region":"IN"}]}'::jsonb, '{}'::jsonb, 'built_in', 'luka-library', 'curated', 'live', 'sweet_side', '3c7fe8f2-eb8d-4cde-a960-5c63622d20dd', array['sweet', 'crisp']::text[], '[{"name":"Ethakka appam","lang":"ml","region":"IN"}]'::jsonb, 15, 10, 4)
