  ('361c8b89-527b-4288-a1be-c82b6528d1cb', 'ng_dodo', '9f5b6cea-dd01-4867-a5c9-a1493ddbeb20', 400, 'ml', 400, 2),
  ('98fcfa0a-198d-40f7-ae6d-21383b7b5ad5', 'jm_rice_and_peas', '5eab6c02-e61c-4d7b-a7e7-cbeb2b35dcc2', 400, 'g', 400, 1),
  ('e4419f26-e1b2-4647-a4e1-a64c3f57d034', 'jm_rice_and_peas', '0ed5e9bf-aa26-4a1f-a3c0-f7a2e097093e', 400, 'ml', 400, 2),
  ('e855db26-e8a0-4cd3-a269-8985c686d6b7', 'jm_rice_and_peas', '3801d0ee-8341-4f23-a3ab-2230b0ef2315', 400, 'g', 400, 3),
  ('edd406dd-5e23-42c3-af41-b4f5aa7eec6c', 'jm_rice_and_peas', '11aef2c8-e0ad-4c7d-afe6-cad723693a91', 60, 'g', 60, 4),
  ('c4975e41-ace7-43d3-a4ef-a3259ecbebe9', 'jm_rice_and_peas', 'd31a03fd-d8b6-4b16-a437-16fe61200de0', 10, 'g', 10, 5),
  ('8850d31e-0f06-437e-a5f5-76b9fabd258b', 'jm_rice_and_peas', 'd5adbdfc-613d-4961-a877-2932c1cfe27b', 3, 'g', 3, 6),
  ('297e13f1-705f-49e5-a7ee-43a2d7cd0b1e', 'jm_rice_and_peas', '43a6977d-e012-4d46-a452-37f8920488e8', 3, 'g', 3, 7),
  ('f08ba277-71c2-421a-a638-8d816fffecf7', 'jm_rice_and_peas', '36ddfc6f-bb6d-4583-a40c-1dcda9fcb36f', 10, 'g', 10, 8),
  ('fa24a8e5-e17e-48a7-abff-8b34ad2718c7', 'jm_fried_ripe_plantain', '1d79e26d-6b7b-48aa-a5d6-9275b1decb49', 750, 'g', 750, 1),
  ('057a1c8a-5377-4b53-a899-d1dd3479c44e', 'jm_fried_ripe_plantain', '9f5b6cea-dd01-4867-a5c9-a1493ddbeb20', 150, 'ml', 150, 2),
  ('99751692-f444-481f-a8f5-f8f951207c8f', 'jm_jerk_chicken', '27b60e7a-a111-4961-ad55-57af8df89412', 1200, 'g', 1200, 1),
  ('f322bda0-7d32-40b2-a7d9-57109e27144b', 'jm_jerk_chicken', '11aef2c8-e0ad-4c7d-afe6-cad723693a91', 100, 'g', 100, 2),
  ('9444ac63-cfc8-4cfe-ad39-452af74230b1', 'jm_jerk_chicken', '36ddfc6f-bb6d-4583-a40c-1dcda9fcb36f', 15, 'g', 15, 3),
  ('d09ee1e5-8163-4c11-a307-e31ae74ab4a9', 'jm_jerk_chicken', '43a6977d-e012-4d46-a452-37f8920488e8', 6, 'g', 6, 4),
  ('f81fec27-0980-4c12-a041-633b05e45eda', 'jm_jerk_chicken', 'd5adbdfc-613d-4961-a877-2932c1cfe27b', 3, 'g', 3, 5),
  ('93fcd906-b636-4c6b-a5d0-bb1557b1c5dc', 'jm_jerk_chicken', 'd31a03fd-d8b6-4b16-a437-16fe61200de0', 20, 'g', 20, 6),
  ('cfcaf90b-4459-4e74-a6f5-06737088dbef', 'jm_jerk_chicken', 'fab0e470-607b-4613-a6d1-62a89a18398f', 20, 'g', 20, 7),
  ('d75fd863-e14a-4954-a168-6117d0ffc768', 'jm_jerk_chicken', 'c5d1944d-6d37-48f3-a82e-4f3450f86232', 70, 'g', 70, 8),
  ('db70d3d7-c550-4607-a57c-57f4d8a10e78', 'jm_jerk_chicken', 'f8f8a656-f6e2-40fb-a1db-b62b6b89c8e8', 30, 'ml', 30, 9),
  ('db327ee0-b265-4b1f-a5f7-1efa7b698fc2', 'jm_jerk_chicken', 'dae2f023-a2fe-48ca-a037-92e42337e10a', 20, 'g', 20, 10),
