  ('101a5662-8170-490d-adba-af828740fe74', 'in_pazham_pori', '1d79e26d-6b7b-48aa-a5d6-9275b1decb49', 750, 'g', 750, 1),
  ('564d6510-2391-4d26-ad35-d623d6a39104', 'in_pazham_pori', 'a71e2281-71fb-4345-a763-0c6f414e388e', 150, 'g', 150, 2),
  ('ca7f2177-b6c8-453a-aacf-d634a3176431', 'in_pazham_pori', 'dae2f023-a2fe-48ca-a037-92e42337e10a', 30, 'g', 30, 3),
  ('8d2dc94b-6792-4200-ab18-3db8f698e79a', 'in_pazham_pori', '8709d937-8714-40dd-a319-e1fa812be816', 1, 'g', 1, 4),
  ('6c420ecc-cd2e-4de1-a0fa-8b7edc672ac7', 'in_pazham_pori', '9f5b6cea-dd01-4867-a5c9-a1493ddbeb20', 500, 'ml', 500, 5)
insert into public.recipe_steps (recipe_id, step_number, instruction, timer_minutes) values
  ('ng_jollof', 1, 'Season 1 kg chicken thighs with 1 tsp curry powder, ½ tsp dried thyme and salt. Roast at 220 °C until golden and cooked through (35 min).', 35),
  ('ng_jollof', 2, 'Blend 4 tomatoes (500 g), 1 red pepper (200 g), 1 scotch bonnet and 1 onion until smooth.', null),
  ('ng_jollof', 3, 'Slice the remaining 1 onion. Heat 5½ tbsp vegetable oil in a heavy pot, fry the onion 3 minutes, then add 70 g tomato paste and fry until it darkens to brick red (5 min).', 5),
  ('ng_jollof', 4, 'Pour in the blend with the rest of the curry and thyme and ¾ tsp bay leaves. Cook uncovered, stirring often, until reduced by half and the oil rises to the top (20 min).', 20),
  ('ng_jollof', 5, 'Rinse 500 g long-grain rice until the water runs clear. Stir it into the base with 700 ml vegetable stock. Cover with foil and a lid and cook on the lowest heat (30 min). Shake the pot instead of stirring.', 30),
  ('ng_jollof', 6, 'Done when the grains are tender but separate. Let a light crust form at the bottom for smoky party flavour, then serve with the chicken.', null),
  ('ng_efo', 1, 'Cut 600 g stewing beef into chunks, season with salt and half the onion, and simmer in 300 ml vegetable stock until tender (30 min). Keep the broth.', 30),
  ('ng_efo', 2, 'Peel 1 kg puna yam, cut into thick rounds and boil in salted water until a knife slides in easily (20 min).', 20),
  ('ng_efo', 3, 'Blend 1 red pepper (200 g) and 1 scotch bonnet coarsely. Wash and roughly chop 600 g spinach, then squeeze out the water.', null),
  ('ng_efo', 4, 'Warm 4 tbsp red palm oil gently (don''t let it smoke). Fry the remaining ½ onion, add the pepper blend and fry until thick (10 min).', 10),
  ('ng_efo', 5, 'Add the beef, a splash of broth and 15 g ground dried crayfish. Fold in the spinach and cook just until wilted and bright green (3 min). Serve with the yam.', 3),
  ('ng_moimoi', 1, 'Soak 400 g black-eyed peas for 15 minutes, then rub between your palms to slip off the skins; rinse until mostly skinless (15 min).', 15),
  ('ng_moimoi', 2, 'Hard-boil 3 eggs (10 min), cool and halve.', 10),
  ('ng_moimoi', 3, 'Blend the beans with 1 red pepper, ½ onion and 250 ml vegetable stock into a smooth, thick batter.', null),
  ('ng_moimoi', 4, 'Stir in 4 tbsp vegetable oil, 10 g ground dried crayfish and salt. Divide into greased ramekins or foil packets and tuck half an egg into each.', null),
  ('ng_moimoi', 5, 'Steam over simmering water, topping up as needed (45 min). Set when a knife comes out clean.', 45),
  ('ng_akara', 1, 'Soak 300 g black-eyed peas 15 minutes and rub off the skins (15 min).', 15),
  ('ng_akara', 2, 'Blend with ½ onion and ½ scotch bonnet using as little water as possible. Whisk the batter for 3 minutes until fluffy — this is what makes akara light.', null),
  ('ng_akara', 3, 'Heat 400 ml vegetable oil to 175 °C. Drop in spoonfuls of batter and fry, turning, until deep golden (6 min).', 6),
  ('ng_akara', 4, 'Drain on paper and serve hot, tucked into 400 g soft white loaf.', null),
  ('ng_yamegg', 1, 'Peel and cube 800 g puna yam; boil in salted water until fork-tender (15 min).', 15),
  ('ng_yamegg', 2, 'Meanwhile dice 2 tomatoes (300 g), ½ onion and ½ scotch bonnet. Fry the onion in 2½ tbsp vegetable oil for 2 minutes, add tomato and scotch and cook down (6 min).', 6),
  ('ng_yamegg', 3, 'Pour in beaten 6 eggs and stir gently until fully set, with no runny parts. Serve over the yam.', null),
  ('ng_peppersoup', 1, 'Cut 1 kg chicken thighs into pieces. Put in a pot with chopped 1 onion, 2 tbsp pepper soup spice, salt and 1.5 L vegetable stock.', null),
  ('ng_peppersoup', 2, 'Bring to a boil, then simmer (25 min).', 25),
  ('ng_peppersoup', 3, 'Add cubed 3 potatoes (600 g) and pounded 1 scotch bonnet; simmer until the potatoes are tender and the chicken is cooked through (15 min).', 15),
  ('ng_peppersoup', 4, 'Tear in 20 g basil / scent leaf (stands in for scent leaf) and serve steaming.', null),
  ('ng_egusi', 1, 'Simmer 600 g stewing beef in 800 ml vegetable stock with half the onion and salt until tender (30 min).', 30),
  ('ng_egusi', 2, 'Blend the remaining ½ onion and mix with 250 g ground egusi and a little water into a thick paste.', null),
  ('ng_egusi', 3, 'Warm 5½ tbsp red palm oil, add the egusi paste in spoonfuls and fry undisturbed for 5 minutes, then stir and fry until curdled and nutty (10 min).', 10),
  ('ng_egusi', 4, 'Add the beef and broth, 1 scotch bonnet and 20 g ground dried crayfish. Simmer (10 min). Fold in chopped 400 g spinach and cook 3 minutes.', 10),
  ('ng_egusi', 5, 'Eba: pour 400 g garri into about 2½ times its volume of just-boiled water, rest 2 minutes, then stir hard into a smooth, firm dough.', null),
  ('gh_redred', 1, 'Simmer 500 g black-eyed peas in plenty of water until soft but holding shape (40 min). Drain.', 40),
  ('gh_redred', 2, 'Fry chopped 1½ onion (200 g) in 4 tbsp red palm oil, add grated 20 g fresh ginger, chopped 3 tomatoes (400 g) and ½ scotch bonnet; cook to a thick sauce (10 min).', 10),
  ('gh_redred', 3, 'Stir in the beans and simmer 5 minutes until everything turns red red.', null),
  ('gh_redred', 4, 'Slice ripe 4 plantains (1 kg) on the diagonal and fry in 100 ml vegetable oil until caramelised on both sides (6 min).', 6),
  ('sn_yassa', 1, 'Marinate 1 kg chicken thighs with the juice of 4 lemons (400 g), 30 g dijon mustard, minced 4 garlic cloves, half the oil and sliced 6 onions (900 g) for at least 30 minutes (30 min).', 30),
  ('sn_yassa', 2, 'Lift out the chicken and sear in the remaining 2 tbsp vegetable oil until browned. Set aside.', null),
  ('sn_yassa', 3, 'Cook the onions from the marinade slowly until soft and golden (20 min), then return the chicken with the marinade and a whole ½ scotch bonnet.', 20),
  ('sn_yassa', 4, 'Cover and simmer until the chicken is cooked through (25 min). Meanwhile cook 400 g long-grain rice.', 25),
  ('cm_pouletdg', 1, 'Season 1 kg chicken thighs with 2 garlic cloves, 15 g fresh ginger and salt; brown in half the 120 ml vegetable oil (10 min).', 10),
  ('cm_pouletdg', 2, 'Fry sliced ripe 4 plantains (1 kg) in the rest of the oil until golden; set aside.', null),
  ('cm_pouletdg', 3, 'Add 1½ onion (200 g), 1½ tomato (200 g), sliced 200 g carrots, 200 g green beans and 1 red pepper (200 g) to the chicken with 200 ml water; simmer until the chicken is cooked through (20 min).', 20),
  ('cm_pouletdg', 4, 'Fold in the plantains and warm through.', null),
  ('et_misir', 1, 'Cook finely chopped 3 onions (400 g) in a dry pot, stirring, until soft and jammy (10 min), then add 4 tbsp vegetable oil.', 10),
  ('et_misir', 2, 'Add 25 g berbere, 3 garlic cloves, 15 g fresh ginger and 30 g tomato paste; cook 3 minutes.', null),
  ('et_misir', 3, 'Add 400 g red lentils and 1 L water; simmer, stirring, until thick and soft (25 min).', 25),
  ('et_misir', 4, 'Serve with injera, or 400 g flatbread / roti / pita if injera isn''t available.', null),
  ('ke_sukuma', 1, 'Brown 400 g lean ground beef in 2 tbsp vegetable oil until no pink remains (6 min).', 6),
  ('ke_sukuma', 2, 'Add 1 onion and 2 tomatoes (300 g); cook down (5 min). Add finely sliced 600 g kale / callaloo greens and cook just until tender (5 min).', 5),
  ('ke_sukuma', 3, 'Ugali: bring 1.2 L water to a boil, gradually add 500 g fine cornmeal / maize flour and stir hard with a wooden spoon until thick and pulling from the sides (10 min).', 10),
  ('za_chakalaka', 1, 'Grill or pan-fry 600 g beef sausage until browned and cooked through (15 min).', 15),
  ('za_chakalaka', 2, 'Chakalaka: fry 1 onion, 1 red pepper (200 g), 2 garlic cloves, ½ scotch bonnet and 1.5 tbsp curry powder in 2 tbsp vegetable oil; add grated 300 g carrots (8 min), then 400 g baked beans; simmer 5 minutes.', 8),
  ('za_chakalaka', 3, 'Pap: whisk 400 g fine cornmeal / maize flour into 1.2 L boiling water, cover and cook on low, stirring now and then (20 min).', 20),
  ('jm_ackee', 1, 'Soak 250 g salted cod overnight, or boil it in fresh water twice for 10 minutes each to remove the salt (20 min). Flake, discarding bones.', 20),
  ('jm_ackee', 2, 'Fry sliced 1 onion, 1 red pepper and ½ scotch bonnet in half the 2½ tbsp vegetable oil with ¾ tsp dried thyme until soft (5 min).', 5),
  ('jm_ackee', 3, 'Add the saltfish and chopped 1½ tomato (200 g); cook 3 minutes.', null),
  ('jm_ackee', 4, 'Drain 540 g ackee and fold in very gently so it stays in pieces. Heat through (3 min).', 3),
  ('jm_ackee', 5, 'Fry sliced 2 plantains (500 g) in the remaining oil until golden.', null),
  ('jm_curry', 1, 'Rub 1.2 kg chicken thighs with half the 30 g curry powder, minced 3 garlic cloves, 1¼ tsp dried thyme, 1¼ tsp ground allspice and salt. Rest 20 minutes, or overnight (20 min).', 20),
  ('jm_curry', 2, 'Toast the remaining curry in hot 2½ tbsp vegetable oil for 1 minute until fragrant, then brown the chicken.', null),
  ('jm_curry', 3, 'Add sliced 1½ onion (200 g), a whole ½ scotch bonnet and 500 ml water. Cover and simmer (30 min).', 30),
  ('jm_curry', 4, 'Add cubed 3 potatoes (500 g) and simmer uncovered until the sauce thickens and the chicken is cooked through (15 min). Serve with 400 g long-grain rice.', 15),
  ('jm_jerk', 1, 'Rub 1 kg chicken thighs with 80 g jerk seasoning paste; marinate at least 30 minutes (overnight is best) (30 min).', 30),
  ('jm_jerk', 2, 'Roast at 220 °C until charred at the edges and cooked through (35 min).', 35),
  ('jm_jerk', 3, 'Rice and peas: bring 400 ml coconut milk, the liquid from 400 g red kidney beans topped up with water to 1 L, 1¼ tsp dried thyme, 1¼ tsp ground allspice, crushed 60 g green onions and a whole ½ scotch bonnet to a simmer.', null),
  ('jm_jerk', 4, 'Add rinsed 500 g long-grain rice and the beans, cover and cook on low until fluffy (25 min). Remove the scotch bonnet before serving.', 25),
  ('jm_porridge', 1, 'Whisk 200 g fine cornmeal / maize flour into 500 ml cold water until no lumps remain.', null),
  ('jm_porridge', 2, 'Bring 600 ml milk and 400 ml coconut milk to a simmer, then whisk in the cornmeal mixture.', null),
  ('jm_porridge', 3, 'Cook on low, stirring often, until thick and smooth (12 min).', 12),
  ('jm_porridge', 4, 'Sweeten with 60 g sugar and finish with ¾ tsp ground nutmeg and ¾ tsp ground cinnamon.', null),
  ('jm_callaloo', 1, 'Mix 300 g all-purpose flour with a pinch of salt and about 150 ml water into a firm dough. Shape into small flat rounds.', null),
  ('jm_callaloo', 2, 'Fry the dumplings in 150 ml vegetable oil over medium heat until golden and hollow-sounding (10 min).', 10),
  ('jm_callaloo', 3, 'Strip and slice 400 g kale / callaloo greens (stands in for callaloo). Melt 30 g butter, soften ½ onion, 2 garlic cloves and ½ scotch bonnet, then add 1 tomato.', null),
  ('jm_callaloo', 4, 'Add the greens with a splash of water, cover and steam until tender (8 min).', 8),
  ('tt_chana', 1, 'Mix 20 g curry powder and 2 tsp cumin with a little water into a paste. Fry in 2½ tbsp vegetable oil until it darkens (2 min).', 2),
  ('tt_chana', 2, 'Add chopped 1 onion and 3 garlic cloves, then cubed 3 potatoes (500 g), drained 800 g chickpeas, ½ scotch bonnet and 500 ml water.', null),
  ('tt_chana', 3, 'Simmer until the potatoes break down and thicken the sauce (20 min). Mash a few chickpeas against the pot.', 20),
  ('tt_chana', 4, 'Stir in 20 g cilantro (stands in for shado beni) and serve with warm 400 g flatbread / roti / pita.', null),
  ('ht_griot', 1, 'Pikliz: shred 300 g green cabbage and 150 g carrots, slice ½ scotch bonnet, pack into a jar and cover with 250 ml white vinegar and a pinch of salt. Chill.', null),
  ('ht_griot', 2, 'Cube 1 kg pork shoulder and marinate with the juice of 1½ orange (300 g) and 2 limes, 4 garlic cloves, 1 onion, 1¼ tsp dried thyme and the remaining scotch (30 min).', 30),
  ('ht_griot', 3, 'Simmer the pork in its marinade plus water to cover until tender (50 min). Drain.', 50),
  ('ht_griot', 4, 'Fry the pork in 4 tbsp vegetable oil until crisp at the edges (10 min). Serve with 400 g long-grain rice and pikliz.', 10),
  ('do_mangu', 1, 'Slice 1½ red onion (200 g) thinly and soak in 2½ tbsp white vinegar with a pinch of salt.', null),
  ('do_mangu', 2, 'Peel 4 green plantains (1 kg), cut into chunks and boil until very soft (20 min).', 20),
  ('do_mangu', 3, 'Mash with 40 g butter and a splash of the cooking water until smooth.', null),
  ('do_mangu', 4, 'Fry 4 eggs in 1½ tbsp vegetable oil until the whites are fully set. Top the mangú with eggs and pickled onions.', null),
  ('cu_moros', 1, 'Sofrito: cook chopped 1 onion, 1 red pepper and 3 garlic cloves in 2½ tbsp olive oil until soft (8 min).', 8),
  ('cu_moros', 2, 'Add 1½ tsp cumin, ¾ tsp dried oregano and ¾ tsp bay leaves, then 400 g long-grain rice; stir 1 minute to toast.', null),
  ('cu_moros', 3, 'Add 800 g black beans with their liquid and 600 ml vegetable stock. Cover and simmer on low (20 min).', 20),
  ('cu_moros', 4, 'Rest 5 minutes off the heat, then fluff.', null),
  ('mx_rancheros', 1, 'Char 3 tomatoes (400 g), ½ onion and 1 jalapeño in a dry pan (6 min), then blend into a salsa and simmer 5 minutes.', 6),
  ('mx_rancheros', 2, 'Warm 400 g black beans and mash lightly.', null),
  ('mx_rancheros', 3, 'Warm 300 g corn tortillas in a dry pan. Fry 8 eggs in 2 tbsp vegetable oil until the whites are set.', null),
  ('mx_rancheros', 4, 'Layer tortillas, beans, egg and salsa. Top with sliced 2 avocados (300 g), crumbled 100 g queso fresco / feta and 20 g cilantro.', null),
  ('mx_tinga', 1, 'Poach 800 g chicken thighs in salted water until cooked through (20 min). Shred.', 20),
  ('mx_tinga', 2, 'Blend 3 tomatoes (400 g), 40 g chipotles in adobo and 2 garlic cloves. Soften sliced 1½ onion (200 g) in 1½ tbsp vegetable oil, add the sauce and simmer (8 min).', 8),
  ('mx_tinga', 3, 'Fold in the chicken and simmer until saucy.', null),
  ('mx_tinga', 4, 'Serve in warm 400 g corn tortillas with shredded 200 g green cabbage, 1 avocado and wedges of 2 limes.', null),
  ('pe_lomo', 1, 'Cook 400 g long-grain rice. Cut 4 potatoes (700 g) into fries and oven-bake at 220 °C until crisp (30 min).', 30),
  ('pe_lomo', 2, 'Slice 700 g beef sirloin into strips. Sear in very hot 2 tbsp vegetable oil in batches until browned (3 min). Remove.', 3),
  ('pe_lomo', 3, 'Stir-fry wedges of 2 red onions (300 g) and ½ jalapeño for 1 minute, add 2 tomatoes (300 g) wedges, 3 tbsp soy sauce and 1 tbsp white vinegar.', null),
  ('pe_lomo', 4, 'Return the beef, toss with the fries and 20 g cilantro. Serve with rice.', null),
  ('br_moqueca', 1, 'Marinate 800 g white fish fillets with the juice of 2 limes, 2 garlic cloves and salt (15 min).', 15),
  ('br_moqueca', 2, 'Layer sliced 1½ onion (200 g), 1 red pepper (200 g) and 2 tomatoes (300 g) in a wide pot and lay the fish on top.', null),
  ('br_moqueca', 3, 'Pour over 400 ml coconut milk and 2 tbsp red palm oil. Cover and simmer gently until the fish flakes (15 min).', 15),
  ('br_moqueca', 4, 'Scatter with 20 g cilantro. Serve with 400 g long-grain rice.', null),
  ('co_arepas', 1, 'Mix 300 g masarepa with 400 ml warm water and salt into a soft dough. Rest (5 min).', 5),
  ('co_arepas', 2, 'Shape 8 patties and cook in a dry pan until crusty on both sides (12 min).', 12),
  ('co_arepas', 3, 'Melt 30 g butter, cook chopped 60 g green onions and 1½ tomato (200 g) for 3 minutes.', null),
  ('co_arepas', 4, 'Add beaten 8 eggs and scramble until fully set. Split the arepas and fill with eggs and 100 g queso fresco / feta.', null),
  ('ma_tagine', 1, 'Soften chopped 1½ onion (200 g) and 3 garlic cloves in 2½ tbsp olive oil (5 min). Add 2 tbsp ras el hanout and cook 1 minute.', 5),
  ('ma_tagine', 2, 'Add chunks of 300 g carrots and 1½ sweet potato (500 g), 400 ml crushed tomatoes / passata and 400 ml water. Simmer (15 min).', 15),
  ('ma_tagine', 3, 'Add 1 zucchini (300 g), drained 800 g chickpeas and 100 g dried apricots. Simmer until all the vegetables are tender (15 min).', 15),
  ('ma_tagine', 4, 'Pour 1¼ times its volume of boiling water over 400 g couscous, cover 5 minutes, then fluff. Serve with 20 g cilantro.', null),
  ('tn_shakshuka', 1, 'Soften sliced 1 onion and 1½ red pepper (300 g) in 2 tbsp olive oil (8 min). Add 2 garlic cloves, 1½ tsp cumin and 1½ tsp smoked paprika.', 8),
  ('tn_shakshuka', 2, 'Pour in 700 ml crushed tomatoes / passata and simmer until thick (10 min).', 10),
  ('tn_shakshuka', 3, 'Make 8 wells and crack in 8 eggs. Cover and cook until the whites are fully set (7 min).', 7),
  ('tn_shakshuka', 4, 'Scatter with 20 g flat-leaf parsley and serve with 400 g soft white loaf.', null),
  ('eg_koshari', 1, 'Slice 3 onions (400 g) thinly and fry in 5½ tbsp vegetable oil until deep brown and crisp (15 min). Keep the oil.', 15),
  ('eg_koshari', 2, 'Boil 250 g red lentils until just tender (15 min); cook 250 g short pasta separately.', 15),
  ('eg_koshari', 3, 'Cook 300 g long-grain rice with the lentils and a spoon of the onion oil, covered on low (18 min).', 18),
  ('eg_koshari', 4, 'Simmer 500 ml crushed tomatoes / passata with 3 garlic cloves, 1½ tsp cumin, ¾ tsp chilli powder / cayenne and 2 tbsp white vinegar (10 min).', 10),
  ('eg_koshari', 5, 'Layer rice and lentils, pasta and 400 g chickpeas; spoon over the sauce and top with the crispy onions.', null),
  ('lb_mujaddara', 1, 'Slice 4 onions (600 g) and cook slowly in 5½ tbsp olive oil until dark golden (20 min). Remove half for the topping.', 20),
  ('lb_mujaddara', 2, 'Add 300 g red lentils, 1½ tsp cumin and 1 L water to the pot; simmer (10 min).', 10),
  ('lb_mujaddara', 3, 'Stir in 250 g long-grain rice, cover and cook on low until tender (20 min).', 20),
  ('lb_mujaddara', 4, 'Mix grated ½ cucumber with 300 g plain yogurt and 10 g mint. Dice the rest with 2 tomatoes (300 g) for a salad.', null),
  ('lb_manakish', 1, 'Mix 40 g za''atar with 4 tbsp olive oil into a loose paste.', null),
  ('lb_manakish', 2, 'Spread over 400 g flatbread / roti / pita and bake at 220 °C until the edges crisp (6 min).', 6),
  ('lb_manakish', 3, 'Serve with sliced 1 cucumber (300 g), 2 tomatoes (250 g), 250 g plain yogurt (or labneh) and 10 g mint.', null),
  ('tr_mercimek', 1, 'Soften chopped 1 onion and 150 g carrots in 30 g butter (5 min). Stir in 30 g tomato paste and 1½ tsp cumin.', 5),
  ('tr_mercimek', 2, 'Add rinsed 300 g red lentils, diced 1 potato and 1.5 L vegetable stock. Simmer until everything is soft (25 min).', 25),
  ('tr_mercimek', 3, 'Blend smooth. Finish with 1¼ tsp smoked paprika sizzled in a little butter and a squeeze of 1 lemon.', null),
  ('ir_kuku', 1, 'Very finely chop 120 g flat-leaf parsley, 120 g cilantro, 30 g dill and 100 g green onions — this is a herb cake bound by egg, not the other way round.', null),
  ('ir_kuku', 2, 'Beat 8 eggs with ¾ tsp turmeric and salt; fold in the herbs and chopped 50 g walnuts.', null),
  ('ir_kuku', 3, 'Pour into a hot pan with 2½ tbsp vegetable oil, cover and cook on low (15 min). Flip (or finish under the grill) until set in the centre (5 min).', 15),
  ('ir_kuku', 4, 'Cut into wedges and serve with 400 g flatbread / roti / pita.', null),
  ('sa_machboos', 1, 'Brown 1 kg chicken thighs in 2½ tbsp vegetable oil; remove. Soften 1½ onion (200 g) and 3 garlic cloves, then add 1.5 tbsp baharat, ¾ tsp ground cinnamon and ¾ tsp ground cardamom.', null),
  ('sa_machboos', 2, 'Add chopped 1½ tomato (200 g), a pierced whole 1 lime and 1 L vegetable stock. Return the chicken and simmer (30 min).', 30),
  ('sa_machboos', 3, 'Lift out the chicken and roast at 220 °C to crisp the skin (15 min).', 15),
  ('sa_machboos', 4, 'Add rinsed 500 g long-grain rice to the broth; cover and cook on low (20 min). Serve the chicken over the rice.', 20),
  ('in_dal', 1, 'Rinse 350 g red lentils; simmer with ¾ tsp turmeric and 1 L water until soft (25 min). Cook 400 g long-grain rice.', 25),
  ('in_dal', 2, 'Fry 1½ tsp cumin in 2½ tbsp vegetable oil until it crackles. Add 1 onion, 3 garlic cloves and 15 g fresh ginger; cook until golden (6 min).', 6),
  ('in_dal', 3, 'Add 1½ tomato (200 g) and ¾ tsp chilli powder / cayenne; cook until jammy, then pour over the dal.', null),
  ('in_dal', 4, 'Finish with 20 g cilantro.', null),
  ('in_poha', 1, 'Rinse 300 g poha in a sieve under running water for 20 seconds; drain and rest.', null),
  ('in_poha', 2, 'Fry 60 g roasted peanuts in 2 tbsp vegetable oil until golden; remove. Add 1½ tsp black mustard seeds until they pop.', null),
  ('in_poha', 3, 'Cook diced 1 potato (200 g) with ¾ tsp turmeric, covered, until tender (8 min). Add 1 onion and 10 g green chillies for 2 minutes.', 8),
  ('in_poha', 4, 'Fold in the poha, peanuts and salt; steam covered 2 minutes. Finish with ½ lemon and 20 g cilantro.', null),
  ('in_palak', 1, 'Blanch 600 g spinach for 1 minute (1 min), plunge into iced water and blend smooth.', 1),
  ('in_palak', 2, 'Fry 1¼ tsp cumin in 2½ tbsp vegetable oil, add 1 onion, 3 garlic cloves and 15 g fresh ginger; cook until golden (8 min). Add 1 tomato and cook down.', 8),
  ('in_palak', 3, 'Stir in the spinach purée and 2 tsp garam masala; simmer 5 minutes.', null),
  ('in_palak', 4, 'Add cubed 400 g paneer and warm through. Serve with 400 g flatbread / roti / pita.', null),
  ('in_omelette', 1, 'Finely chop ½ onion, 1 tomato, 10 g green chillies and 20 g cilantro; beat into 8 eggs with salt.', null),
  ('in_omelette', 2, 'Cook in batches in 1½ tbsp vegetable oil until just set (3 min); fold.', 3),
  ('in_omelette', 3, 'Serve with warm 400 g flatbread / roti / pita.', null),
  ('pk_karahi', 1, 'Sear 1 kg chicken thighs in 4 tbsp vegetable oil over high heat (6 min).', 6),
  ('pk_karahi', 2, 'Add 4 garlic cloves and half the 40 g fresh ginger; stir 1 minute. Add halved 5 tomatoes (600 g), cover and cook until soft (10 min). Pull out the skins.', 10),
  ('pk_karahi', 3, 'Cook uncovered, stirring, until the oil separates and the chicken is cooked through (10 min).', 10),
  ('pk_karahi', 4, 'Stir in 150 g plain yogurt, 2 tsp garam masala, sliced 20 g green chillies and the rest of the ginger in thin strips. Garnish with 20 g cilantro; serve with 400 g flatbread / roti / pita.', null),
  ('lk_dhal', 1, 'Simmer 300 g red lentils with ¾ tsp turmeric, half the onion and 600 ml water until soft (15 min).', 15),
  ('lk_dhal', 2, 'Stir in 400 ml coconut milk; simmer 5 minutes.', null),
  ('lk_dhal', 3, 'Fry 2 garlic cloves and the remaining ½ onion in 1½ tbsp vegetable oil; pour over the dhal. Cook 300 g long-grain rice.', null),
  ('lk_dhal', 4, 'Pol sambol: rub 100 g desiccated coconut with 1¼ tsp chilli powder / cayenne, salt and the juice of 1 lime.', null),
  ('cn_congee', 1, 'Simmer 250 g long-grain rice with 2 L vegetable stock, sliced 40 g fresh ginger and whole 400 g chicken thighs, partly covered (20 min).', 20),
  ('cn_congee', 2, 'Lift out the chicken once cooked through; shred it.', null),
  ('cn_congee', 3, 'Keep simmering, stirring now and then, until silky (50 min).', 50),
  ('cn_congee', 4, 'Top with the chicken, 60 g green onions, 2 tbsp soy sauce and ½ tbsp toasted sesame oil.', null),
  ('cn_tomatoegg', 1, 'Cook 400 g long-grain rice. Beat 8 eggs with salt.', null),
  ('cn_tomatoegg', 2, 'Scramble the eggs in half the 2½ tbsp vegetable oil until just set; remove.', null),
  ('cn_tomatoegg', 3, 'Fry 6 tomatoes (800 g) wedges in the remaining oil with 10 g sugar and 1 tbsp soy sauce until saucy (5 min).', 5),
  ('cn_tomatoegg', 4, 'Return the eggs, fold together and top with 60 g green onions.', null),
  ('jp_salmon', 1, 'Cook 400 g long-grain rice. Mix 60 g white miso and 2 tbsp mirin; brush over 600 g salmon fillets.', null),
  ('jp_salmon', 2, 'Grill or bake at 220 °C until glazed and the fish flakes (10 min).', 10),
  ('jp_salmon', 3, 'Steam halved 400 g bok choy (3 min); dress with 1 tbsp soy sauce.', 3),
  ('jp_salmon', 4, 'Sprinkle 10 g sesame seeds over everything.', null),
  ('jp_breakfast', 1, 'Cook 300 g long-grain rice.', null),
  ('jp_breakfast', 2, 'Beat 8 eggs with 10 g sugar and ½ tbsp soy sauce. Cook in thin layers in a pan wiped with ½ tbsp vegetable oil, rolling each layer (8 min).', 8),
  ('jp_breakfast', 3, 'Bring 1 L water to a bare simmer, whisk in 50 g white miso (don''t boil), add cubed 300 g firm tofu and 40 g green onions.', null),
  ('kr_bibimbap', 1, 'Cook 400 g long-grain rice.', null),
  ('kr_bibimbap', 2, 'Brown 400 g lean ground beef with 2 garlic cloves and 2 tbsp soy sauce until no pink remains (6 min).', 6),
  ('kr_bibimbap', 3, 'Blanch 300 g spinach and 200 g bean sprouts separately (1 min); season each with a little 1½ tbsp toasted sesame oil. Stir-fry thin strips of 200 g carrots (2 min).', 1),
  ('kr_bibimbap', 4, 'Fry 4 eggs until the whites are set.', null),
  ('kr_bibimbap', 5, 'Arrange everything over the rice and serve with 60 g gochujang.', null),
  ('th_green', 1, 'Cook 400 g long-grain rice. Fry 60 g thai green curry paste in 1 tbsp vegetable oil with a few spoons of the thick top of the 800 ml coconut milk until fragrant (3 min).', 3),
  ('th_green', 2, 'Add sliced 700 g chicken thighs; cook 3 minutes, then the rest of the coconut milk.', null),
  ('th_green', 3, 'Add 1 eggplant (300 g) and 200 g green beans; simmer until the chicken is cooked through (12 min).', 12),
  ('th_green', 4, 'Season with 2 tbsp fish sauce and 10 g sugar; tear in 20 g basil / scent leaf.', null),
  ('vn_bun', 1, 'Slice 600 g pork shoulder thin; marinate with minced 40 g lemongrass, 2 garlic cloves, half the 2½ tbsp fish sauce and half the 30 g sugar (15 min).', 15),
  ('vn_bun', 2, 'Grill or pan-sear until caramelised and cooked through (8 min).', 8),
  ('vn_bun', 3, 'Cook 400 g rice vermicelli as the pack says, then rinse cold.', null),
  ('vn_bun', 4, 'Mix the remaining fish sauce and sugar with the juice of 1 lime and 120 ml water. Build bowls with noodles, 200 g lettuce, ½ cucumber (200 g), 150 g carrots, 20 g mint, the pork and crushed 60 g roasted peanuts.', null),
  ('ph_adobo', 1, 'Combine 1.2 kg chicken thighs, 120 ml soy sauce, smashed 8 garlic cloves, 1¼ tsp bay leaves and 1½ tsp whole black peppercorns; rest 20 minutes (20 min).', 20),
  ('ph_adobo', 2, 'Brown the chicken in 1½ tbsp vegetable oil, add the marinade and 120 ml white vinegar. Don''t stir until it boils — that mellows the vinegar.', null),
  ('ph_adobo', 3, 'Simmer covered until cooked through (25 min), then uncovered to reduce to a glossy sauce (10 min).', 25),
  ('ph_adobo', 4, 'Serve with 500 g long-grain rice.', null),
  ('id_nasigoreng', 1, 'Use cold cooked rice: cook 350 g long-grain rice the day before, or cook it and spread it on a tray to cool (20 min).', 20),
  ('id_nasigoreng', 2, 'Stir-fry thin strips of 300 g chicken thighs in 2½ tbsp vegetable oil until cooked through (5 min). Add 1 onion, 2 garlic cloves and 1¼ tsp chilli powder / cayenne.', 5),
  ('id_nasigoreng', 3, 'Add the rice and 3 tbsp kecap manis; toss over high heat until hot (4 min).', 4),
  ('id_nasigoreng', 4, 'Fry 4 eggs until set and serve on top with sliced ½ cucumber (200 g).', null),
  ('it_ceci', 1, 'Soften ½ onion, 2 garlic cloves and ¾ tsp dried rosemary in 2½ tbsp olive oil (5 min).', 5),
  ('it_ceci', 2, 'Add 800 g chickpeas, 300 ml crushed tomatoes / passata and 1 L vegetable stock; simmer, then blend a third of it (10 min).', 10),
  ('it_ceci', 3, 'Add 350 g short pasta and cook in the soup until al dente, adding water if needed (11 min).', 11),
  ('gr_souvlaki', 1, 'Marinate cubed 800 g chicken thighs with the juice of 1 lemon, 1¼ tsp dried oregano, half the 3 garlic cloves and 2½ tbsp olive oil (15 min).', 15),
  ('gr_souvlaki', 2, 'Thread onto skewers and grill or pan-sear until cooked through (12 min).', 12),
  ('gr_souvlaki', 3, 'Tzatziki: grate half the 1 cucumber (300 g), squeeze it dry and mix with 300 g plain yogurt and the remaining garlic.', null),
  ('gr_souvlaki', 4, 'Serve with 400 g flatbread / roti / pita, chopped 2 tomatoes (300 g), the rest of the cucumber and ½ red onion.', null),
  ('gr_yogurt', 1, 'Spoon 800 g plain yogurt into bowls.', null),
  ('gr_yogurt', 2, 'Top with 340 g mixed berries, chopped 80 g walnuts and a drizzle of 60 g honey.', null),
  ('es_tortilla', 1, 'Thinly slice 4 potatoes (800 g) and 1½ onion (200 g); poach gently in 200 ml olive oil until soft, not browned (20 min). Drain, keeping the oil.', 20),
  ('es_tortilla', 2, 'Beat 8 eggs with salt and fold in the potatoes; rest (10 min).', 10),
  ('es_tortilla', 3, 'Cook in a little of the oil over medium-low (8 min), flip using a plate, and cook until set in the centre (5 min).', 8),
  ('ca_oats', 1, 'The night before, stir 320 g rolled oats, 40 g chia seeds, 800 ml milk and 2½ tbsp maple syrup together in jars. Chill overnight.', null),
  ('ca_oats', 2, 'In the morning, top with 340 g mixed berries.', null),
  ('us_sheetpan', 1, 'Heat the oven to 220 °C. Toss cubed 2 sweet potatoes (800 g) with half the 2½ tbsp olive oil; roast (15 min).', 15),
  ('us_sheetpan', 2, 'Add 800 g chicken thighs rubbed with 1½ tsp smoked paprika, 2 garlic cloves and the rest of the oil; roast (15 min).', 15),
  ('us_sheetpan', 3, 'Add 500 g broccoli florets and roast until charred at the edges and the chicken is cooked through (12 min).', 12),
  ('fx_jerkjollof', 1, 'Rub 1 kg chicken thighs with 60 g jerk seasoning paste; marinate (20 min). Roast at 220 °C until cooked through (35 min).', 20),
  ('fx_jerkjollof', 2, 'Blend 3 tomatoes (400 g), 1 red pepper (200 g), ½ scotch bonnet and half the 1½ onion (200 g).', null),
  ('fx_jerkjollof', 3, 'Fry the rest of the onion and 50 g tomato paste in 4 tbsp vegetable oil until brick red, add the blend, 1¼ tsp dried thyme and ¾ tsp ground allspice; reduce by half (20 min).', 20),
  ('fx_jerkjollof', 4, 'Add rinsed 500 g long-grain rice and 700 ml vegetable stock; cover tightly and steam on low (30 min). Serve under the jerk chicken.', 30),
  ('fx_plantainshak', 1, 'Fry diced ripe 2 plantains (500 g) in half the 2½ tbsp vegetable oil until caramelised; set aside.', null),
  ('fx_plantainshak', 2, 'Soften ½ onion, 1 red pepper (200 g) and ½ scotch bonnet in the remaining oil with 1¼ tsp cumin (6 min). Add 500 ml crushed tomatoes / passata; simmer (8 min).', 6),
  ('fx_plantainshak', 3, 'Stir in the plantain, make wells and crack in 8 eggs; cover until the whites are set (7 min).', 7),
  ('fx_suya', 1, 'Quick pikliz: shred 300 g green cabbage and 150 g carrots, add sliced ½ scotch bonnet, cover with 200 ml white vinegar and salt (15 min).', 15),
  ('fx_suya', 2, 'Suya spice: grind 60 g roasted peanuts with 2 tsp chilli powder / cayenne, grated 10 g fresh ginger and salt. Coat thin strips of 700 g beef sirloin.', null),
  ('fx_suya', 3, 'Sear in a very hot pan until charred (5 min). Cook 400 g long-grain rice.', 5),
  ('fx_suya', 4, 'Serve the beef over rice with sliced ½ onion, 1½ tomato (200 g) and the pikliz.', null),
  ('fx_currychana_plantain', 1, 'Toast 2 tbsp curry powder in 2½ tbsp vegetable oil for 1 minute, then soften 1 onion, 2 garlic cloves and ½ scotch bonnet (5 min).', 5),
  ('fx_currychana_plantain', 2, 'Add drained 800 g chickpeas and 400 ml coconut milk; simmer (12 min). Cook 400 g long-grain rice.', 12),
  ('fx_currychana_plantain', 3, 'Fold in sliced 250 g kale / callaloo greens and cook until tender (4 min).', 4),
  ('fx_currychana_plantain', 4, 'Fry sliced ripe 2 plantains (500 g) until golden and serve alongside.', null),
  ('ng_rice_and_beans', 1, 'Pick through 300 g honey beans for stones, rinse, and boil in plenty of water until just tender but holding shape (40 min). Don''t salt yet: salt toughens the skins.', 40),
  ('ng_rice_and_beans', 2, 'Rinse 400 g parboiled long-grain rice until the water runs clear. Add it to the beans with 300 ml vegetable stock and enough hot water to cover by 2 cm. Cover and cook on low until the rice is soft and the water is absorbed (25 min).', 25),
  ('ng_rice_and_beans', 3, 'Warm 4 tbsp red palm oil gently (no smoke), fry sliced 1 onion and pounded ½ scotch bonnet until soft and fragrant (5 min), then stir in 10 g ground dried crayfish.', 5),
  ('ng_rice_and_beans', 4, 'Fold the palm-oil sauce through the rice and beans and season with salt. The grains should be separate, the beans creamy inside.', null),
  ('ng_dodo', 1, 'Use plantains with mostly black skins: they''re sweetest. Peel 4 plantains (1 kg) and cut on the diagonal into 1 cm slices; salt lightly.', null),
  ('ng_dodo', 2, 'Heat 400 ml vegetable oil in a deep pan to about 175 °C: a slice should sizzle at once.', null),
  ('ng_dodo', 3, 'Fry in batches without crowding until deep golden with caramelised edges, turning once (4 min).', 4),
  ('ng_dodo', 4, 'Drain on paper. Dodo is done when the edges are dark amber and the centre is soft and sweet.', null),
  ('jm_rice_and_peas', 1, 'Pour 400 g red kidney beans with their liquid and 400 ml coconut milk into a pot. Add crushed 2 garlic cloves, 1¼ tsp dried thyme, 1¼ tsp ground allspice and bruised 60 g green onions; top up with water to make about 900 ml liquid.', null),
  ('jm_rice_and_peas', 2, 'Bring to a simmer, add a whole 1 scotch bonnet (don''t burst it: it perfumes rather than burns) and season well with salt.', null),
  ('jm_rice_and_peas', 3, 'Stir in rinsed 400 g long-grain rice, cover tightly and cook on the lowest heat (25 min) until the liquid is absorbed.', 25),
  ('jm_rice_and_peas', 4, 'Lift out the scotch bonnet and scallion. Fluff with a fork: the rice should be pale pink and fragrant with coconut.', null),
  ('jm_fried_ripe_plantain', 1, 'Peel ripe 3 plantains (750 g) (yellow with plenty of black spots) and slice lengthwise or on a long diagonal, about 1 cm thick.', null),
  ('jm_fried_ripe_plantain', 2, 'Shallow-fry in 150 ml vegetable oil over medium heat, turning once, until both sides are golden brown and glossy (6 min).', 6),
  ('jm_fried_ripe_plantain', 3, 'Drain briefly. Serve warm beside jerk, ackee or rice and peas.', null),
  ('jm_jerk_chicken', 1, 'Blend 100 g green onions, 1½ scotch bonnet, 2½ tsp ground allspice, 1¼ tsp dried thyme, 4 garlic cloves, 20 g fresh ginger, the juice of 1 lime, 2 tbsp soy sauce, 20 g sugar and 2 tbsp vegetable oil into a thick marinade.', null),
  ('jm_jerk_chicken', 2, 'Slash 1.2 kg chicken thighs to the bone, rub the marinade into every cut and marinate at least 2 hours, ideally overnight (120 min).', 120),
  ('jm_jerk_chicken', 3, 'Roast at 200 °C, or grill over medium coals, turning, until charred at the edges and cooked through (45 min).', 45),
  ('jm_jerk_chicken', 4, 'Rest 5 minutes. Jerk is ready when the skin is blistered and dark in places and the juices run clear.', null),
  ('in_pazham_pori', 1, 'Whisk 150 g all-purpose flour, 30 g sugar, ½ tsp turmeric and a pinch of salt with about 180 ml water into a smooth batter that coats a spoon.', null),
  ('in_pazham_pori', 2, 'Peel ripe 3 plantains (750 g) (Kerala nendran if you can find it) and slice lengthwise into thin, long strips.', null),
  ('in_pazham_pori', 3, 'Heat 500 ml vegetable oil to about 175 °C. Dip each strip in batter and fry until puffed and golden on both sides (4 min).', 4),
  ('in_pazham_pori', 4, 'Drain and serve hot with tea, the way it''s eaten at Kerala tea shops in the evening.', null)
insert into public.meal_plates (id, slug, title, summary, country_code, cuisine_tags, verification_status) values
  ('b4f80bc8-622e-4b00-ad14-dc1397d4c004', 'ng-rice-and-beans-with-dodo', 'Nigerian Rice & Beans with Dodo', 'Creamy honey beans and rice in palm-oil pepper sauce, with sweet fried plantain on the side.', 'NG', array['Nigeria']::text[], 'curated'),
  ('6f72decb-2bf5-4ebc-a245-48bd38a6301f', 'jm-rice-and-peas-jerk-chicken-fried-plantain', 'Jamaican Rice & Peas with Jerk Chicken & Fried Plantain', 'Sunday-style plate: smoky jerk chicken, coconut rice and peas, and ripe fried plantain.', 'JM', array['Jamaica']::text[], 'curated')
insert into public.meal_plate_items (plate_id, recipe_id, role_in_plate, is_anchor, sort_order) values
  ('b4f80bc8-622e-4b00-ad14-dc1397d4c004', 'ng_rice_and_beans', 'main_one_pot', true, 1),
  ('b4f80bc8-622e-4b00-ad14-dc1397d4c004', 'ng_dodo', 'sweet_side', false, 2),
  ('6f72decb-2bf5-4ebc-a245-48bd38a6301f', 'jm_jerk_chicken', 'protein_main', true, 1),
  ('6f72decb-2bf5-4ebc-a245-48bd38a6301f', 'jm_rice_and_peas', 'base_starch', false, 2),
  ('6f72decb-2bf5-4ebc-a245-48bd38a6301f', 'jm_fried_ripe_plantain', 'sweet_side', false, 3)
